const Btn = ({ icon: Icon, label, onClick, disabled }) => (
  <button
    type="button"
    onClick={onClick}
    disabled={disabled}
    className="h-[28px] px-2.5 flex items-center gap-1.5 rounded-sm border border-gray-300 bg-white text-[12px] font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-40"
  >
    <Icon className="w-3.5 h-3.5 text-gray-500" />
    {label}
  </button>
);

export default function FoundationToolbar({
  title,
  subtitle,
  backTo,
  total,
  saving,
  dirty,
  lastSavedAt,
  autoSave,
  onToggleAutoSave,
  canUndo,
  canRedo,
  onUndo,
  onRedo,
  onSave,
  onSaveAndExit,
  onSaveAsCopy,
  onSaveAsTemplate,
  onTemplates,
  onSwapToBrickStone,
  onShareLink,
  onHelp,
  onBack,
  pricingUnavailable = false,
}) {
  return (
    <div className="bg-white border border-gray-200 rounded-sm p-3 mb-3">
      <div className="flex items-center gap-3 mb-2">
        {onBack ? (
          <button
            type="button"
            onClick={onBack}
            className="h-[28px] px-2.5 flex items-center gap-1 rounded-sm border border-gray-300 text-[12px] font-medium text-gray-700 hover:bg-gray-50"
          >
            <ArrowLeft className="w-3.5 h-3.5" aria-hidden="true" /> Back
          </button>
        ) : (
          <Link
            to={backTo}
            className="h-[28px] px-2.5 flex items-center gap-1 rounded-sm border border-gray-300 text-[12px] font-medium text-gray-700 hover:bg-gray-50"
          >
            <ArrowLeft className="w-3.5 h-3.5" aria-hidden="true" /> Back
          </Link>
        )}
        <div>
          <h1 className="text-[17px] font-bold text-gray-900 leading-tight">{title}</h1>
          <p className="text-[11px] text-gray-500">{subtitle}</p>
        </div>
      </div>

      <div className="flex items-center gap-2 flex-wrap">
        <span className="text-[13px] font-bold text-gray-900 mr-1">Total: {pricingUnavailable ? <span className="text-amber-700">Pricing unavailable</span> : money(total)}</span>
        <Btn icon={HelpCircle} label="Help" onClick={onHelp} />
        <Btn icon={Undo2} label="Undo" onClick={onUndo} disabled={!canUndo} />
        <Btn icon={Redo2} label="Redo" onClick={onRedo} disabled={!canRedo} />
        <Btn icon={LayoutTemplate} label="Templates" onClick={onTemplates} />
        <Btn icon={BookmarkPlus} label="Save as Template" onClick={onSaveAsTemplate} />
        <Btn icon={Copy} label="Save As Copy" onClick={onSaveAsCopy} />
        {onSwapToBrickStone ? <Btn icon={ArrowLeftRight} label="Swap to BrickStone" onClick={onSwapToBrickStone} /> : null}
        {onShareLink ? <Btn icon={Link2} label="Share Link" onClick={onShareLink} /> : null}
        <button
          type="button"
          onClick={onSaveAndExit}
          disabled={saving}
          className="h-[28px] px-3 flex items-center gap-1.5 rounded-sm bg-lime-300 border border-lime-400 text-[12px] font-bold text-gray-800 hover:bg-lime-200 disabled:opacity-60"
        >
          <Save className="w-3.5 h-3.5" aria-hidden="true" /> {saving ? "Saving…" : "Save & Exit"}
        </button>

        <button
          type="button"
          onClick={onToggleAutoSave}
          className={`ml-1 w-[38px] h-[20px] rounded-full transition-colors relative ${
            autoSave ? "bg-gray-800" : "bg-gray-300"
          }`}
          title="Auto-save"
        >
          <span
            className={`absolute top-[2px] w-[16px] h-[16px] bg-white rounded-full transition-all ${
              autoSave ? "left-[20px]" : "left-[2px]"
            }`}
          />
        </button>
        <span className="text-[10px] font-semibold text-gray-500 uppercase tracking-wide">
          Auto-save
        </span>
        <span className="text-[11px] text-gray-400">
          {saving ? "Saving…" : dirty ? "Not yet saved" : "All changes saved"}{!saving && !dirty && lastSavedAt ? ` · Last saved ${new Date(lastSavedAt).toLocaleString()}` : ""}
        </span>
        <button
          type="button"
          onClick={onSave}
          disabled={saving || !dirty}
          className="h-[28px] px-3 rounded-sm border border-gray-300 text-[12px] font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-40"
        >
          Save
        </button>
      </div>
    </div>
  );
}

import React from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Trash2, Plus, PenLine } from "lucide-react";
import { money } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";
import { foundationWallPricingIssues } from "./wallCalculator";
import WallShapeEditor from "./WallShapeEditor";

const heightInput = (value) => value === "" ? "" : Number.isFinite(Number(value)) ? Number(value) : value;

function WallRow({ wall, index, options, pricing, onChange, onRemove }) {
  const c = wall.calculatedCosts || {};
  const set = (changes) => onChange(index, changes);
  // Settings-aware issues arrive from calcProject; the local re-derive covers
  // consumers that cannot supply them (no settings visibility).
  const pricingIssues = pricing?.issues ?? foundationWallPricingIssues(wall, options, index);
  const pricingUnavailable = pricing?.available === false || pricingIssues.length > 0;
  const amt = (v) => (hasFoundationCostSnapshot(v) ? money(v) : "Not saved");
  const [showEditor, setShowEditor] = React.useState(false);
  const fieldIssue = (field) => pricingIssues.some((i) => i.field === field);
  const describedBy = (field) => (fieldIssue(field) ? `wall-${index}-pricing` : undefined);

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-3 space-y-3">
      <div className="flex items-center justify-between gap-2">
        <Input
          className="min-w-0 max-w-[220px]"
          value={wall.name || ""}
          placeholder={`Wall ${index + 1}`}
          onChange={(e) => set({ name: e.target.value })}
        />
        <div className="flex shrink-0 items-center gap-3">
          <span className="whitespace-nowrap font-bold text-gray-900">{amt(c.totalCost)}</span>
          <Button variant="ghost" size="icon" onClick={() => onRemove(index)}>
            <Trash2 className="w-4 h-4 text-red-500" aria-hidden="true" />
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
        <label className="text-xs text-gray-500">
          Height (in)
          <Input
            type="number"
            step="any"
            value={wall.heightInches ?? ""}
            onChange={(e) => set({ heightInches: heightInput(e.target.value) })}
            aria-label="Wall height (in)"
            aria-invalid={fieldIssue("heightInches") || undefined}
            aria-describedby={describedBy("heightInches")}
          />
        </label>
        <label className="text-xs text-gray-500">
          Mortar gap (in)
          <Input
            type="number"
            step="0.125"
            min="0"
            value={wall.mortarGapInches ?? 0.375}
            placeholder="0.375"
            onChange={(e) => set({ mortarGapInches: heightInput(e.target.value) })}
            aria-label="Wall mortar gap (in)"
            aria-invalid={fieldIssue("mortarGapInches") || undefined}
            aria-describedby={describedBy("mortarGapInches")}
          />
        </label>
        <label className="text-xs text-gray-500 md:col-span-2">
          Wall material
          <select
            className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
            value={wall.materialId || ""}
            aria-label="Wall material"
            aria-invalid={fieldIssue("materialId") || undefined}
            aria-describedby={describedBy("materialId")}
            onChange={(e) => set({ materialId: e.target.value })}
          >
            <option value="">Select material…</option>
            {wall.materialId && !options.some((o) => o.id === wall.materialId) && (
              <option value={wall.materialId} disabled>{`Catalog material unavailable (${wall.materialId})`}</option>
            )}
            {options.map((o) => (
              <option key={o.id} value={o.id}>
                {o.material_name}
              </option>
            ))}
          </select>
          {wall.materialId && !options.some((o) => o.id === wall.materialId) && (
            <span className="block text-[10px] text-amber-700 mt-1">Catalog material unavailable; current pricing needs review.</span>
          )}
        </label>
      </div>

      <div className="rounded-lg bg-slate-50 p-2 space-y-2">
        <label className="flex items-center gap-2 text-xs font-medium text-gray-700">
          <input
            type="checkbox"
            checked={!!wall.includeInternalWall}
            onChange={(e) => set({ includeInternalWall: e.target.checked })}
          />
          Internal fill wall
        </label>
        {wall.includeInternalWall && (
          <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
            <label className="text-xs text-gray-500 md:col-span-2">
              Fill material
              <select
                className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                value={wall.internalMaterialId || ""}
                aria-label="Internal wall material"
                aria-invalid={fieldIssue("internalMaterialId") || undefined}
                aria-describedby={describedBy("internalMaterialId")}
                onChange={(e) => set({ internalMaterialId: e.target.value })}
              >
                <option value="">Select material…</option>
                {wall.internalMaterialId && !options.some((o) => o.id === wall.internalMaterialId) && (
                  <option value={wall.internalMaterialId} disabled>{`Catalog material unavailable (${wall.internalMaterialId})`}</option>
                )}
                {options.map((o) => (
                  <option key={o.id} value={o.id}>
                    {o.material_name}
                  </option>
                ))}
              </select>
              {wall.internalMaterialId && !options.some((o) => o.id === wall.internalMaterialId) && (
                <span className="block text-[10px] text-amber-700 mt-1">Catalog material unavailable; current pricing needs review.</span>
              )}
            </label>
            <label className="text-xs text-gray-500">
              Fill height (in)
              <Input
                type="number"
                step="any"
                value={wall.internalWallHeightInches ?? wall.heightInches ?? ""}
                onChange={(e) => set({ internalWallHeightInches: heightInput(e.target.value) })}
                aria-label="Internal wall height (in)"
                aria-invalid={fieldIssue("internalWallHeightInches") || undefined}
                aria-describedby={describedBy("internalWallHeightInches")}
              />
            </label>
            <label className="text-xs text-gray-500">
              Fill mortar gap (in)
              <Input
                type="number"
                step="0.125"
                min="0"
                value={wall.internalMortarGapInches ?? 0.375}
                placeholder="0.375"
                onChange={(e) => set({ internalMortarGapInches: heightInput(e.target.value) })}
                aria-label="Internal wall mortar gap (in)"
                aria-invalid={fieldIssue("internalMortarGapInches") || undefined}
                aria-describedby={describedBy("internalMortarGapInches")}
              />
            </label>
          </div>
        )}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-2 text-xs text-gray-600">
        <div>Units: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.totalBricks) ? Math.round(c.totalBricks) : "Not saved"}</span></div>
        <div>Courses: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.numCourses) ? Math.ceil(c.numCourses) : "Not saved"}</span></div>
        <div>Material: <span className="font-semibold text-gray-900">{amt(c.materialCost)}</span></div>
        <div>Mortar: <span className="font-semibold text-gray-900">{amt(c.mortarCost)}</span></div>
        <div>Labor: <span className="font-semibold text-gray-900">{amt(c.laborCost)}</span></div>
        <div>Labor hrs: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.laborHours) ? c.laborHours.toFixed(1) : "Not saved"}</span></div>
        <div>Linear in: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.totalLinearInches) ? Math.round(c.totalLinearInches) : "Not saved"}</span></div>
        {pricingUnavailable && <div className="col-span-full text-[10px] font-semibold text-amber-700">Saved amounts (not current pricing)</div>}
        {pricingIssues.length > 0 && (
          <div role="status" className="col-span-full text-[10px] text-amber-700 space-y-0.5" id={`wall-${index}-pricing`}>
            {pricingIssues.map((issue) => <p key={`${issue.field}-${issue.code}`}>{issue.message}</p>)}
          </div>
        )}
      </div>

      <div className="flex items-center gap-2">
        <Button variant="outline" size="sm" onClick={() => setShowEditor((v) => !v)}
          aria-expanded={showEditor}
          aria-invalid={fieldIssue("shape") || undefined}
          aria-describedby={describedBy("shape")}>
          <PenLine className="w-4 h-4" aria-hidden="true" /> {showEditor ? "Hide outline" : "Wall outline"}
        </Button>
        {fieldIssue("shape") ? (
          <span className="text-xs text-amber-600">
            Outline geometry needs repair before repricing - see diagnostics above.
          </span>
        ) : !wall.shape?.segments?.length ? (
          <span className="text-xs text-amber-600">
            No outline yet - draw the wall footprint before estimating quantities.
          </span>
        ) : null}
      </div>

      {showEditor && (
        <WallShapeEditor shape={wall.shape} onChange={(shape) => set({ shape })} />
      )}
    </div>
  );
}

export default function FoundationWallsPanel({ walls = [], options = [], onChange, wallPricing = [] }) {
  const patchWall = (index, changes) =>
    onChange(walls.map((w, i) => (i === index ? { ...w, ...changes } : w)));

  const removeWall = (index) => {
    const name = walls[index]?.name || `Wall ${index + 1}`;
    if (!window.confirm(`Remove ${name}? Wall caps attached to it are retained for review.`)) return;
    onChange(walls.filter((_, i) => i !== index));
  };

  const addWall = () =>
    onChange([
      ...walls,
      { name: `Wall ${walls.length + 1}`, heightInches: 24, mortarGapInches: 0.375, offsetFraction: 0.5 },
    ]);

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <h2 className="font-semibold text-gray-900">Masonry Walls</h2>
        <Button variant="outline" size="sm" onClick={addWall}>
          <Plus className="w-4 h-4" aria-hidden="true" /> Wall
        </Button>
      </div>

      {walls.length === 0 ? (
        <div className="text-center py-8 bg-white rounded-xl border border-dashed border-gray-300 text-gray-500 text-sm">
          No walls on this section.
        </div>
      ) : (
        walls.map((wall, index) => (
          <WallRow
            key={wall.component_id || index}
            wall={wall}
            index={index}
            options={options}
            pricing={wallPricing[index]}
            onChange={patchWall}
            onRemove={removeWall}
          />
        ))
      )}
    </div>
  );
}

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Trash2, Plus } from "lucide-react";
import { money } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";
import { foundationWallCapCatalogIssues, wallCapInputNumber, wallCapCutLengthValue } from "./wallCapCalculator";

export default function FoundationWallCapsPanel({ caps = [], walls = [], options = [], onChange }) {
  const patchCap = (index, changes) =>
    onChange(caps.map((c, i) => (i === index ? { ...c, ...changes } : c)));

  const removeCap = (index) => {
    if (!window.confirm(`Remove cap ${index + 1}?`)) return;
    onChange(caps.filter((_, i) => i !== index));
  };

  const addCap = () => {
    const inv = options[0];
    const stockLength = wallCapInputNumber(inv?.cap_stock_length_inches);
    onChange([
      ...caps,
      {
        id: `cap_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
        cap_inventory_id: inv?.id || "",
        wall_component_id: walls[0]?.component_id || "",
        wall_index: walls.length ? 0 : undefined,
        segment_component_id: walls[0]?.shape?.segments?.[0]?.component_id || "",
        segment_index: walls[0]?.shape?.segments?.length ? 0 : undefined,
        position_along_segment_inches: 0,
        length_inches: stockLength !== null && stockLength > 0 ? stockLength : "",
        rotation_offset_degrees: 0,
        lateral_offset_inches: 0,
      },
    ]);
  };

  const capIssues = foundationWallCapCatalogIssues(caps, options);
  const unavailableCaps = new Set(capIssues.filter(issue => issue.code !== "wall_cap_cost_total_invalid").map(issue => issue.index));
  const geometryIssues = (index) => capIssues.filter(issue => issue.index === index && ["length_inches", "cap_stock_length_inches"].includes(issue.field));

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="font-semibold text-gray-900">Wall Caps</h2>
          <p className="text-xs text-gray-500">Full stock price is charged per cut piece.</p>
        </div>
        <Button variant="outline" size="sm" onClick={addCap} disabled={options.length === 0}>
          <Plus className="w-4 h-4" aria-hidden="true" /> Cap
        </Button>
      </div>

      {options.length === 0 && (
        <div className="text-[11px] text-amber-800 bg-amber-50 border border-amber-200 rounded px-2 py-1.5">
          Wall cap catalog unavailable — existing rows remain editable; new caps cannot be added.
        </div>
      )}
      {caps.length === 0 ? (
        <div className="text-center py-6 bg-white rounded-xl border border-dashed border-gray-300 text-gray-500 text-sm">
          No caps on this section.
        </div>
      ) : (
        caps.map((cap, index) => (
          <div key={cap.component_id || cap.id || index} className="bg-white rounded-xl border border-gray-200 p-3">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-2 items-end">
              <label className="text-xs text-gray-500 md:col-span-2">
                Cap material
                <select
                  className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                  value={cap.cap_inventory_id || ""}
                  aria-label="Cap material"
                  onChange={(e) => {
                    patchCap(index, {
                      cap_inventory_id: e.target.value,
                    });
                  }}
                >
                  <option value="">Select cap…</option>
                  {cap.cap_inventory_id && !options.some((o) => o.id === cap.cap_inventory_id) && (
                    <option value={cap.cap_inventory_id} disabled>{`Catalog cap unavailable (${cap.cap_inventory_id})`}</option>
                  )}
                  {options.map((o) => (
                    <option key={o.id} value={o.id}>
                      {o.material_name}
                    </option>
                  ))}
                </select>
                {cap.cap_inventory_id && !options.some((o) => o.id === cap.cap_inventory_id) && (
                  <span className="block text-[10px] text-amber-700 mt-1">Catalog cap unavailable; current pricing needs review.</span>
                )}
              </label>
              <label className="text-xs text-gray-500">
                Wall
                <select
                  className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                  value={cap.wall_component_id ?? ""}
                  aria-label="Cap wall"
                  onChange={(e) => {
                    const id = e.target.value;
                    const i = walls.findIndex((w) => w.component_id === id);
                    patchCap(index, {
                      wall_component_id: id,
                      wall_index: id === "" || i < 0 ? undefined : i,
                      segment_component_id: "",
                      segment_index: undefined,
                    });
                  }}
                >
                  <option value="">Unassigned</option>
                  {cap.wall_component_id && !walls.some((w) => w.component_id === cap.wall_component_id) && (
                    <option value={cap.wall_component_id} disabled>{`Missing wall (${String(cap.wall_component_id).slice(0, 18)}…)`}</option>
                  )}
                  {walls.map((w, i) => (
                    <option key={w.component_id || i} value={w.component_id || ""}>
                      {w.name || `Wall ${i + 1}`}
                    </option>
                  ))}
                </select>
              </label>
              <label className="text-xs text-gray-500">
                Segment
                <select
                  className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                  value={cap.segment_component_id ?? ""}
                  aria-label="Cap segment"
                  onChange={(e) => {
                    const id = e.target.value;
                    const wall = walls.find((w) => w.component_id === cap.wall_component_id);
                    const segs = wall?.shape?.segments || [];
                    const i = segs.findIndex((sg) => sg.component_id === id);
                    patchCap(index, {
                      segment_component_id: id,
                      segment_index: id === "" || i < 0 ? undefined : i,
                    });
                  }}
                >
                  <option value="">Unassigned</option>
                  {cap.segment_component_id && !(walls.find((w) => w.component_id === cap.wall_component_id)?.shape?.segments || []).some((sg) => sg.component_id === cap.segment_component_id) && (
                    <option value={cap.segment_component_id} disabled>{`Missing segment (${String(cap.segment_component_id).slice(0, 18)}…)`}</option>
                  )}
                  {(walls.find((w) => w.component_id === cap.wall_component_id)?.shape?.segments || []).map((sg, i) => (
                    <option key={sg.component_id || i} value={sg.component_id || ""}>
                      {`Segment ${i + 1}`}
                    </option>
                  ))}
                </select>
              </label>
              <label className="text-xs text-gray-500">
                Cut length (in)
                <Input
                  type="number"
                  step="any"
                  value={wallCapInputNumber(wallCapCutLengthValue(cap)) === null ? "" : wallCapCutLengthValue(cap)}
                  aria-label={`Cap ${index + 1} cut length (inches)`}
                  aria-invalid={geometryIssues(index).some((i) => i.field === "length_inches") || undefined}
                  aria-describedby={geometryIssues(index).length ? `wall-cap-${index}-geometry` : undefined}
                  onChange={(e) => {
                    const raw = e.target.value;
                    const parsed = wallCapInputNumber(raw);
                    patchCap(index, { length_inches: parsed === null ? raw : parsed });
                  }}
                />
              </label>
            </div>
            {geometryIssues(index).length > 0 && (
              <div id={`wall-cap-${index}-geometry`} className="mt-1 text-[11px] text-amber-700 space-y-0.5">
                {geometryIssues(index).map((issue) => (
                  <p key={issue.code}>{issue.message}</p>
                ))}
              </div>
            )}
            <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-2 mt-2 text-xs text-gray-600">
              <span>
                {unavailableCaps.has(index) ? "Saved stock length: " : "Stock length: "}<span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(cap.stock_length_inches) && cap.stock_length_inches > 0 ? cap.stock_length_inches + String.fromCharCode(34) : "Not saved"}</span>
              </span>
              <div className="ml-auto flex items-center gap-3">
                <span className="font-bold text-gray-900">{hasFoundationCostSnapshot(cap.cost) ? money(cap.cost) : "Not saved"}</span>
                {unavailableCaps.has(index) && <span className="text-[10px] text-amber-700">Saved amounts (not current pricing)</span>}
                <Button variant="ghost" size="icon" onClick={() => removeCap(index)}>
                  <Trash2 className="w-4 h-4 text-red-500" aria-hidden="true" />
                </Button>
              </div>
            </div>
          </div>
        ))
      )}
    </div>
  );
}

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Trash2, Plus } from "lucide-react";
import { money } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";

const heightInput = (value) => value === "" ? "" : Number.isFinite(Number(value)) ? Number(value) : value;

export default function FoundationPolesPanel({ poles = [], options = [], items = [], onChange, polePricing = [] }) {
  const patchPole = (index, changes) =>
    onChange(poles.map((p, i) => (i === index ? { ...p, ...changes } : p)));

  const removePole = (index) => {
    if (!window.confirm(`Remove Pole ${index + 1}? Cabinets mounted on it are retained for review.`)) return;
    onChange(poles.filter((_, i) => i !== index));
  };

  const addPole = () =>
    onChange([
      ...poles,
      { pole_id: options[0]?.id || "", height_inches: 120, y_offset_inches: 42, include_pole_painting: false },
    ]);

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="font-semibold text-gray-900">Poles</h2>
          <p className="text-xs text-gray-500">
            Priced on total length — height above grade plus depth in the ground.
          </p>
        </div>
        <Button variant="outline" size="sm" onClick={addPole} disabled={options.length === 0}>
          <Plus className="w-4 h-4" aria-hidden="true" /> Pole
        </Button>
      </div>

      {options.length === 0 && (
        <div className="text-[11px] text-amber-800 bg-amber-50 border border-amber-200 rounded px-2 py-1.5">
          Pole catalog unavailable — existing rows remain editable; new poles cannot be added.
        </div>
      )}
      {poles.length === 0 ? (
        <div className="text-center py-6 bg-white rounded-xl border border-dashed border-gray-300 text-gray-500 text-sm">
          No poles on this section.
        </div>
      ) : (
        poles.map((pole, index) => {
          const issues = polePricing[index]?.issues || [];
          const pricingUnavailable = polePricing[index]?.available === false;
          const fieldIssue = (field) => issues.some((i) => i.field === field);
          const describedBy = issues.length ? `pole-${index}-pricing` : undefined;
          return (
            <div key={pole.component_id || index} className="bg-white rounded-xl border border-gray-200 p-3">
              <div className="grid grid-cols-2 md:grid-cols-5 gap-2 items-end">
                <label className="text-xs text-gray-500 md:col-span-2">
                  Pole
                  <select
                    className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                    value={pole.pole_id || ""}
                    aria-label="Pole material"
                    aria-invalid={fieldIssue("pole_id") || undefined}
                    aria-describedby={fieldIssue("pole_id") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { pole_id: e.target.value })}
                  >
                    <option value="">Select pole…</option>
                    {pole.pole_id && !options.some((o) => o.id === pole.pole_id) && (
                      <option value={pole.pole_id} disabled>{`Catalog pole unavailable (${pole.pole_id})`}</option>
                    )}
                    {options.map((o) => (
                      <option key={o.id} value={o.id}>
                        {o.material_name}
                      </option>
                    ))}
                  </select>
                  {pole.pole_id && !options.some((o) => o.id === pole.pole_id) && (
                    <span className="block text-[10px] text-amber-700 mt-1">Catalog pole unavailable; current pricing needs review.</span>
                  )}
                </label>
                <label className="text-xs text-gray-500">
                  Height above grade (in)
                  <Input
                    type="number"
                    step="any"
                    value={pole.height_inches ?? ""}
                    aria-label={`Pole ${index + 1} height above grade (inches)`}
                    aria-invalid={fieldIssue("height_inches") || undefined}
                    aria-describedby={fieldIssue("height_inches") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { height_inches: heightInput(e.target.value) })}
                  />
                </label>
                <label className="text-xs text-gray-500">
                  Depth in ground (in)
                  <Input
                    type="number"
                    step="any"
                    value={pole.y_offset_inches ?? ""}
                    aria-label={`Pole ${index + 1} depth in ground (inches)`}
                    aria-invalid={fieldIssue("y_offset_inches") || undefined}
                    aria-describedby={fieldIssue("y_offset_inches") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { y_offset_inches: heightInput(e.target.value) })}
                  />
                </label>
                <label className="text-xs text-gray-500">
                  Foundation
                  <select
                    className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                    value={pole.foundation_component_id ?? ""}
                    aria-label="Pole foundation"
                    onChange={(e) => {
                      const id = e.target.value;
                      const i = items.findIndex((it) => it.component_id === id);
                      patchPole(index, {
                        foundation_component_id: id,
                        foundation_idx: id === "" || i < 0 ? undefined : i,
                      });
                    }}
                  >
                    <option value="">Unassigned</option>
                    {pole.foundation_component_id && !items.some((it) => it.component_id === pole.foundation_component_id) && (
                      <option value={pole.foundation_component_id} disabled>{`Missing foundation (${String(pole.foundation_component_id).slice(0, 18)}…)`}</option>
                    )}
                    {items.map((it, i) => (
                      <option key={it.component_id || i} value={it.component_id || ""}>
                        {it.description || `Foundation ${i + 1}`}
                      </option>
                    ))}
                  </select>
                </label>
              </div>

              <div className="flex items-center justify-between mt-2">
                <label className="flex items-center gap-1.5 text-xs font-medium text-gray-700">
                  <input
                    type="checkbox"
                    checked={!!pole.include_pole_painting}
                    aria-invalid={issues.some((i) => i.code === "pole_paint_setting_unavailable") || undefined}
                    aria-describedby={issues.some((i) => i.code === "pole_paint_setting_unavailable") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { include_pole_painting: e.target.checked })}
                  />
                  Paint pole
                </label>
                <div className="flex items-center gap-3 text-xs text-gray-600">
                  <span>Pole {hasFoundationCostSnapshot(pole.pole_cost) ? money(pole.pole_cost) : "Not saved"}</span>
                  <span>Paint {hasFoundationCostSnapshot(pole.pole_painting_cost) ? money(pole.pole_painting_cost) : "Not saved"}</span>
                  <span className="font-bold text-gray-900 text-sm">{hasFoundationCostSnapshot(pole.total_cost) ? money(pole.total_cost) : "Not saved"}</span>
                  {pricingUnavailable && <span className="col-span-full text-[10px] text-amber-700">Saved amounts (not current pricing)</span>}
                  <Button variant="ghost" size="icon" onClick={() => removePole(index)}>
                    <Trash2 className="w-4 h-4 text-red-500" aria-hidden="true" />
                  </Button>
                </div>
              </div>
              {issues.length > 0 && (
                <div role="status" className="mt-2 text-[10px] text-amber-700 space-y-0.5" id={`pole-${index}-pricing`}>
                  {issues.map((issue) => <p key={`${issue.field}-${issue.code}`}>{issue.message}</p>)}
                </div>
              )}
            </div>
          );
        })
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import { Trash2, Wrench } from 'lucide-react';
import { money, calcEquipmentPricing, equipmentCostTotal } from './foundationCalc';
import { hasFoundationCostSnapshot } from './foundationCatalogIntegrity';
import { setFoundationEquipmentCount } from './foundationEquipmentBindings';

const fin = (v) => Number.isFinite(v);
const intQty = (v) => fin(v) && Number.isInteger(v) && v >= 0;
// Blank-preserving draft coercion (same rule as the wall/pole panels): a blank
// draft stays blank, a numeric draft becomes a number, and a malformed draft
// is stored verbatim so the pricing diagnostics can flag it — never coerced.
const equipmentInputValue = (value) => value === "" ? "" : Number.isFinite(Number(value)) ? Number(value) : value;

function OverrideChip({ label, value, onClear, moneyVal = false, invalid = false }) {
  if (value === undefined || value === null) return null;
  return (
    <span className={`inline-flex items-center gap-1 rounded-sm px-1.5 py-0.5 text-[10px] font-semibold ${invalid ? 'bg-red-100 text-red-800 border border-red-300' : 'bg-amber-100 text-amber-800'}`}>
      {label}: {moneyVal && typeof value === 'number' ? money(value) : String(value)}
      <button type="button" aria-label={`Clear ${label}`} onClick={onClear} className={invalid ? 'text-red-900 hover:underline' : 'text-amber-900 hover:underline'}>Clear</button>
    </span>
  );
}

function EquipmentCard({ entry, detail, index, inventory, onUpdate, onRemove, showMiscAttachments }) {
  const [err, setErr] = useState('');
  useEffect(() => { setErr(''); }, [entry]);
  const eq = detail.equipment; // may be undefined when missing
  const issues = detail.issues || [];
  const broken = issues.length > 0;
  const fieldIssue = (field) => issues.some((i) => i.field === field);
  const describedBy = (field) => (fieldIssue(field) ? `equipment-${index}-pricing` : undefined);
  const update = (next) => onUpdate(index, next);
  const setQty = (kind, id, quantity) => {
    try {
      const next = setFoundationEquipmentCount(entry, { kind, id, quantity });
      setErr('');
      update(next);
    } catch (e) { setErr(e.message || 'Quantity change rejected.'); }
  };
  const changeQty = (kind, id, raw) => {
    // Valid input reaches the shared draft immediately, including keyboard saves.
    if (raw === '') return;
    const n = Number(raw);
    if (!intQty(n)) { setErr('Quantity must be a whole number 0 or greater.'); return; }
    setQty(kind, id, n);
  };

  const eqOptions = inventory.filter(i => i.material_type === 'excavation_equipment');
  const compatibleAtts = inventory.filter(a =>
    a.material_type === 'attachment'
    && (showMiscAttachments || !a.is_miscellaneous_attachment)
    && (eq?.compatible_attachment_ids || []).includes(a.id));
  const activeParents = detail.attachmentRows.filter(r => r.quantity > 0 && r.inventory);
  const compatibleSubs = inventory.filter(s =>
    s.material_type === 'sub_attachment'
    && (showMiscAttachments || !s.is_miscellaneous_attachment)
    && activeParents.some(r => (eq?.compatible_attachment_ids || []).includes(r.id)
      && (r.inventory.compatible_sub_attachment_ids || []).includes(s.id)));
  const selectedAttIds = new Set(detail.attachmentMode === 'normalized'
    ? detail.attachmentRows.map(r => r.id)
    : detail.attachmentRows.filter(r => r.quantity !== 0).map(r => r.id));
  const selectedSubIds = new Set(detail.subAttachmentRows.filter(r => r.quantity !== 0).map(r => r.id));

  // legacy_ids: group occurrence counts per lead recipe; normalized keeps each raw row.
  const attView = detail.attachmentMode === 'legacy_ids'
    ? [...new Set(detail.attachmentRows.map(r => r.id))].map(id => ({
        id,
        quantity: detail.attachmentRows.filter(r => r.id === id).length,
        inventory: detail.attachmentRows.find(r => r.id === id)?.inventory,
        row: detail.attachmentRows.find(r => r.id === id),
        group: detail.attachmentRows.filter(r => r.id === id).length > 1,
      }))
    : detail.attachmentRows.map(row => ({ id: row.id, quantity: row.quantity, inventory: row.inventory, row, group: false }));
  const dupNormIds = detail.attachmentMode === 'normalized'
    ? new Set(detail.attachmentRows.map(r => r.id).filter((id) => detail.attachmentRows.filter(r => r.id === id).length > 1))
    : new Set();

  const periodOptions = ['day', 'week', 'month'].filter(p => eq ? fin(eq[`cost_per_${p}`]) : true);
  const savedPeriod = detail.rentalPeriod;
  if (savedPeriod && !periodOptions.includes(savedPeriod)) periodOptions.push(savedPeriod);
  const customQtyActive = entry.custom_qty !== undefined && entry.custom_qty !== null;

  const cardTotal = !broken
    ? money(detail.totalCost)
    : hasFoundationCostSnapshot(detail.totalCost) ? money(detail.totalCost) : 'Not saved';
  const lineAmt = (v) => (broken ? 'Unavailable' : money(v));

  const attRow = (a, key) => {
    const inv = a.inventory;
    const missing = !inv;
    const dupNorm = detail.attachmentMode === 'normalized' && dupNormIds.has(a.id);
    const disabledQty = dupNorm;
    return (
      <div key={key} className={`flex items-center justify-between gap-2 p-2 rounded-lg border text-xs ${a.quantity > 0 ? 'bg-amber-50 border-amber-300' : 'bg-slate-50 border-slate-200'}`}>
        <div className="min-w-0">
          <div className="font-medium text-slate-800 truncate">{inv?.material_name || `Catalog item unavailable (${a.id})`}</div>
          <div className="text-[10px] text-slate-500">
            {missing && <span className="text-amber-700 font-semibold">Unavailable — review. </span>}
            {dupNorm && <span className="text-amber-700 font-semibold">Duplicate rows — quantity editing disabled. </span>}
            {detail.attachmentMode === 'normalized' && a.row.sourceRecord?.qty === 0 && <span>qty 0 priced as 1. </span>}
            {a.group && <span>legacy duplicate ids ×{a.quantity} — catalog per-unit rate only. </span>}
            {!missing && inv && !a.group && hasFoundationCostSnapshot(a.row.cost) && <span>{money(a.row.cost)}</span>}
            {!missing && a.group && fin(inv?.cost_per_day) && <span>rate {money(inv.cost_per_day)}/day</span>}
          </div>
        </div>
        <div className="flex items-center gap-1 shrink-0">
          {dupNorm ? (
            <Button size="sm" variant="outline" className="h-6 text-[10px]" onClick={() => setQty('attachment', a.id, 0)}>Remove all duplicates</Button>
          ) : (
            <input
              type="number" min="0" disabled={disabledQty} aria-label={`Attachment qty ${inv?.material_name || a.id}`}
              className="h-7 w-14 rounded-md border border-input px-1 text-xs disabled:opacity-40"
              value={a.quantity}
              onChange={(e) => changeQty('attachment', a.id, e.target.value)}
            />
          )}
        </div>
      </div>
    );
  };

  const subRow = (s, key) => {
    const inv = s.inventory;
    const missing = !inv;
    const parentLinked = activeParents.some(r => (r.inventory.compatible_sub_attachment_ids || []).includes(s.id));
    return (
      <div key={key} className="flex items-center justify-between gap-2 p-2 rounded-lg border text-xs bg-slate-50 border-slate-200">
        <div className="min-w-0">
          <div className="font-medium text-slate-800 truncate">{inv?.material_name || `Catalog item unavailable (${s.id})`}</div>
          <div className="text-[10px] text-slate-500">
            {missing && <span className="text-amber-700 font-semibold">Unavailable — review. </span>}
            {!missing && !parentLinked && <span className="text-amber-700 font-semibold">No selected parent attachment links this item. </span>}
            {!missing && hasFoundationCostSnapshot(s.cost) && <span>{money(s.cost)}</span>}
          </div>
        </div>
        <input
          type="number" min="0" aria-label={`Sub attachment qty ${inv?.material_name || s.id}`}
          className="h-7 w-14 rounded-md border border-input px-1 text-xs"
          value={s.quantity}
          onChange={(e) => changeQty('sub_attachment', s.id, e.target.value)}
        />
      </div>
    );
  };

  return (
    <Card data-equipment-index={index} className="border border-indigo-200 shadow-sm overflow-hidden mb-4">
      <CardHeader className="py-3 px-4 bg-indigo-50/60 border-b border-indigo-100">
        <div className="flex items-start justify-between">
          <div className="flex flex-col gap-1.5">
            <div className="flex items-center gap-2 flex-wrap">
              <CardTitle className="text-sm font-semibold">{eq?.material_name || `Equipment ${index + 1}`}</CardTitle>
              {eq?.equipment_type && <Badge variant="outline" className="text-xs">{eq.equipment_type}</Badge>}
              {eq?.rental_company && <span className="text-xs text-slate-500">{eq.rental_company}</span>}
              {broken && <Badge variant="secondary" className="text-xs text-amber-800">Saved amounts (not current pricing)</Badge>}
              <Badge variant="secondary" className="text-xs">Total: {cardTotal}</Badge>
            </div>
            {eq?.notes && <p className="text-xs text-slate-500 leading-relaxed max-w-3xl">{eq.notes}</p>}
          </div>
          <div className="flex gap-1">
            <Button size="sm" variant="ghost" className="text-red-500" aria-label={`Remove equipment ${index + 1}`} onClick={onRemove}>
              <Trash2 className="w-3 h-3" aria-hidden="true" />
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent className="px-4 pb-4 space-y-4">
        {broken && (
          <ul role="status" id={`equipment-${index}-pricing`} className="list-disc pl-5 text-[11px] text-amber-800">
            {issues.map((i, k) => <li key={k}>{i.message}</li>)}
          </ul>
        )}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <div>
            <Label className="text-xs">Equipment</Label>
            <Select
              value={entry.equipment_id || ''}
              onValueChange={(v) => update({ ...entry, equipment_id: v })}
            >
              <SelectTrigger className="h-8"><SelectValue placeholder="Select equipment…" /></SelectTrigger>
              <SelectContent>
                {entry.equipment_id && !eqOptions.some(o => o.id === entry.equipment_id) && (
                  <SelectItem value={entry.equipment_id} disabled>{`Catalog equipment unavailable (${entry.equipment_id})`}</SelectItem>
                )}
                {eqOptions.map(o => <SelectItem key={o.id} value={o.id}>{o.material_name}</SelectItem>)}
              </SelectContent>
            </Select>
            {eq && (eq.compatible_attachment_ids?.length || eq.compatible_sub_attachment_ids?.length) === 0 ? null : null}
            {broken && <p className="text-[10px] text-amber-700 mt-0.5">Reassigning preserves selected attachments/overrides — review compatibility.</p>}
          </div>
          <div>
            <Label className="text-xs">Rental Period</Label>
            <Select value={detail.rentalPeriod} onValueChange={(v) => update({ ...entry, rental_period: v })}>
              <SelectTrigger className="h-8"><SelectValue /></SelectTrigger>
              <SelectContent>
                {periodOptions.map(p => (
                  <SelectItem key={p} value={p}>
                    {p === 'day' ? `Daily (${fin(eq?.cost_per_day) ? money(eq.cost_per_day) : '?'}/day)`
                      : p === 'week' ? `Weekly (${fin(eq?.cost_per_week) ? money(eq.cost_per_week) : '?'}/wk)`
                      : p === 'month' ? `Monthly (${fin(eq?.cost_per_month) ? money(eq.cost_per_month) : '?'}/mo)`
                      : `Review (${savedPeriod})`}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label className="text-xs">Duration {customQtyActive && <span className="text-amber-700">(custom qty override active — editing duration does not clear it)</span>}</Label>
            <input
              type="number" aria-label="Rental duration" min={1} step="any"
              className="flex h-8 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm"
              value={entry.rental_duration ?? ""}
              placeholder="1"
              aria-invalid={fieldIssue("rental_duration") || undefined}
              aria-describedby={describedBy("rental_duration")}
              onChange={(e) => update({ ...entry, rental_duration: equipmentInputValue(e.target.value) })}
            />
          </div>
          <div className="flex items-end pb-1">
            <div className="flex items-center gap-2">
              <Checkbox
                checked={entry.include_delivery || false}
                onCheckedChange={(v) => update({ ...entry, include_delivery: v })}
                id={`delivery-${entry._id || index}`}
              />
              <Label htmlFor={`delivery-${entry._id || index}`} className="text-xs cursor-pointer">
                Include Delivery {fin(eq?.pickup_delivery_cost) ? `(${money(eq.pickup_delivery_cost)})` : ''}
              </Label>
            </div>
          </div>
        </div>
        <div className="flex flex-wrap gap-2">
          <OverrideChip label="Custom rate" value={entry.custom_rate} moneyVal invalid={fieldIssue('custom_rate')} onClear={() => update({ ...entry, custom_rate: null })} />
          <OverrideChip label="Custom qty" value={entry.custom_qty} invalid={fieldIssue('custom_qty')} onClear={() => update({ ...entry, custom_qty: null })} />
          <OverrideChip label={`Custom delivery${entry.include_delivery ? '' : ' (inactive — delivery excluded)'}`} value={entry.custom_delivery_charge} moneyVal invalid={fieldIssue('custom_delivery_charge')} onClear={() => update({ ...entry, custom_delivery_charge: null })} />
        </div>
        {err && <p role="alert" className="text-[11px] text-red-700">{err}</p>}
        <div className="grid grid-cols-3 gap-2 text-xs text-slate-600">
          <div>Base: <span className="font-semibold text-slate-900">{lineAmt(detail.baseCost)}</span></div>
          <div>Delivery: <span className="font-semibold text-slate-900">{lineAmt(detail.deliveryCost)}</span></div>
          <div>Total: <span className="font-semibold text-slate-900">{cardTotal}</span></div>
        </div>

        <div>
          <Label className="text-xs font-semibold text-slate-600 uppercase tracking-wide mb-2 block">
            <Wrench className="w-3 h-3 inline mr-1" aria-hidden="true" /> Attachments
          </Label>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
            {attView.filter(a => detail.attachmentMode === 'normalized' || a.quantity !== 0).map((a, k) => attRow(a, k))}
          </div>
          {compatibleAtts.filter(a => !selectedAttIds.has(a.id)).length > 0 && eq && (
            <div className="mt-2">
              <Select value="" onValueChange={(v) => v && setQty('attachment', v, 1)}>
                <SelectTrigger className="h-8"><SelectValue placeholder="Add attachment…" /></SelectTrigger>
                <SelectContent>
                  {compatibleAtts.filter(a => !selectedAttIds.has(a.id)).map(a => (
                    <SelectItem key={a.id} value={a.id}>{a.material_name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}
          {attView.some(a => a.inventory && !(eq?.compatible_attachment_ids || []).includes(a.id)) && (
            <p className="text-[10px] text-amber-700 mt-1">Selected item incompatible with this parent — review.</p>
          )}
        </div>

        {detail.subAttachmentRows.filter(s => s.quantity !== 0).length > 0 && (
          <div>
            <Label className="text-xs font-semibold text-slate-600 uppercase tracking-wide mb-2 block">Sub-attachments</Label>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              {detail.subAttachmentRows.filter(s => s.quantity !== 0).map((s, k) => subRow(s, k))}
            </div>
          </div>
        )}
        {compatibleSubs.filter(s => !selectedSubIds.has(s.id)).length > 0 && eq && (
          <div>
            <Select value="" onValueChange={(v) => v && setQty('sub_attachment', v, 1)}>
              <SelectTrigger className="h-8"><SelectValue placeholder="Add sub-attachment…" /></SelectTrigger>
              <SelectContent>
                {compatibleSubs.filter(s => !selectedSubIds.has(s.id)).map(s => (
                  <SelectItem key={s.id} value={s.id}>{s.material_name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

export default function EquipmentTab({ foundationItems = [], inventory = [], selectedEquipmentList = [], onUpdate, markDirty }) {
  const [showAllEquipment, setShowAllEquipment] = useState(false);
  const [showMiscAttachments, setShowMiscAttachments] = useState(false);

  const pricingRows = calcEquipmentPricing(selectedEquipmentList, inventory);
  const total = equipmentCostTotal(pricingRows.map(r => r.pricedEntry));
  const incomplete = pricingRows.some(r => r.issues.length);

  const sortByOrder = (rows) => [...rows].sort((a, b) => (a.sort_order ?? 0) - (b.sort_order ?? 0));
  const excavation = sortByOrder(inventory.filter(i => i.material_type === 'excavation_equipment' && !i.is_non_excavation_equipment));
  const nonExcavation = sortByOrder(inventory.filter(i => i.material_type === 'excavation_equipment' && i.is_non_excavation_equipment));
  const types = new Set((foundationItems || []).map(f => f.foundation_type));
  const hasPillar = types.has('pillar');
  const hasSpread = types.has('spread_foot');
  const filteredExcavation = showAllEquipment || (!hasPillar && !hasSpread) ? excavation
    : excavation.filter(e => (hasPillar && e.is_pillar_excavation) || (hasSpread && e.is_spread_foot_excavation));
  const filteredNonExcavation = nonExcavation;

  const addEquipment = (eqId) => {
    if (!eqId || eqId === '_none') return;
    const eqItem = inventory.find(i => i.id === eqId);
    const newEntry = {
      _id: `eq_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      equipment_id: eqId,
      rental_period: 'day',
      rental_duration: 1,
      include_delivery: (eqItem?.pickup_delivery_cost || 0) > 0,
      attachment_counts: {},
      sub_attachment_counts: {},
    };
    onUpdate([...selectedEquipmentList, newEntry]);
    markDirty();
  };

  const removeEquipment = (idx) => {
    const eq = inventory.find(i => i.id === selectedEquipmentList[idx]?.equipment_id);
    if (!window.confirm(`Remove ${eq?.material_name || 'this equipment'}?`)) return;
    onUpdate(selectedEquipmentList.filter((_, i) => i !== idx));
    markDirty();
  };

  const updateEntry = (idx, updated) => {
    const arr = [...selectedEquipmentList];
    arr[idx] = updated;
    onUpdate(arr);
    markDirty();
  };

  const addSelect = (label, rows, placeholder) => (
    <div className="flex-1 min-w-[260px]">
      <Label className="text-xs font-semibold text-indigo-900 uppercase tracking-wide">{label}</Label>
      <Select value="" onValueChange={addEquipment}>
        <SelectTrigger className="h-9 mt-1"><SelectValue placeholder={placeholder} /></SelectTrigger>
        <SelectContent>
          {rows.length === 0 ? <SelectItem value="_none" disabled>No equipment available</SelectItem>
            : rows.map(eq => <SelectItem key={eq.id} value={eq.id}>{eq.material_name}</SelectItem>)}
        </SelectContent>
      </Select>
    </div>
  );

  return (
    <div className="space-y-4">
      <Card className="border-indigo-200 bg-indigo-50/50 shadow-sm mb-4">
        <CardContent className="py-3 px-4">
          <div className="flex items-center gap-6 mb-4 pb-4 border-b border-indigo-100">
            <div className="flex items-center gap-2">
              <Checkbox id="showAllEq" checked={showAllEquipment} onCheckedChange={setShowAllEquipment} />
              <Label htmlFor="showAllEq" className="text-sm cursor-pointer text-indigo-900 font-medium">Show all equipment</Label>
            </div>
            <div className="flex items-center gap-2">
              <Checkbox id="showMiscAtt" checked={showMiscAttachments} onCheckedChange={setShowMiscAttachments} />
              <Label htmlFor="showMiscAtt" className="text-sm cursor-pointer text-indigo-900 font-medium">Show Miscellaneous Attachments</Label>
            </div>
          </div>
          <div className="flex flex-wrap items-end gap-4">
            {addSelect('Add Excavation Equipment', filteredExcavation, 'Select excavation equipment to add…')}
            {addSelect('Add Non-Excavation Equipment', filteredNonExcavation, 'Select non-excavation equipment to add…')}
          </div>
        </CardContent>
      </Card>

      {incomplete && (
        <div role="alert" className="rounded border border-amber-300 bg-amber-50 px-3 py-2 text-[13px] text-amber-800 font-semibold">
          Pricing unavailable: selected materials or rental items need attention. Saved/known amounts only.
        </div>
      )}

      {selectedEquipmentList.length === 0 && (
        <Card className="border-dashed">
          <CardContent className="py-10 text-center text-slate-400">
            <Wrench className="w-8 h-8 mx-auto mb-2" aria-hidden="true" />
            <p className="font-medium">No equipment added yet</p>
            <p className="text-sm mt-1">Select equipment from the dropdown above.</p>
          </CardContent>
        </Card>
      )}

      {selectedEquipmentList.map((entry, idx) => (
        <EquipmentCard
          key={entry.component_id || entry._id || idx}
          entry={entry}
          detail={pricingRows[idx]}
          index={idx}
          inventory={inventory}
          onUpdate={updateEntry}
          onRemove={() => removeEquipment(idx)}
          showMiscAttachments={showMiscAttachments}
        />
      ))}

      {selectedEquipmentList.length > 0 && (
        <Card className="bg-amber-50 border-amber-200">
          <CardContent className="py-3 px-4 flex items-center justify-between">
            <span className="font-medium text-amber-800">Total Equipment Cost</span>
            <span className="text-lg font-bold text-amber-700">{incomplete ? 'Pricing unavailable' : money(total)}</span>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

