                    >
                      <option value="">Select parent…</option>
                      {items.map((it, ix) => (
                        <option key={it.component_id || ix} value={`foundation:${it.component_id}`}>{it.description || `Foundation ${ix + 1}`}</option>
                      ))}
                      {poles.map((po, ix) => (
                        <option key={po.component_id || ix} value={`pole:${po.component_id}`}>{po.description || `Pole ${ix + 1}`}</option>
                      ))}
                    </select>
                  </label>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState } from "react";
import { Trash2 } from "lucide-react";
import {
  LANDSCAPE_MATERIALS,
  GRID_COLS,
  GRID_ROWS,
  landscapeSummary,
  materialByKey,
} from "./landscapeMaterials";
import { money } from "./foundationCalc";

const sqftLabel = (l) =>
  Number.isFinite(l.sqft) ? `${l.sqft.toFixed(0)} sq ft`
    : `${l.cells} cell${l.cells === 1 ? "" : "s"} — area unavailable`;
const costLabel = (v) => (Number.isFinite(v) ? money(v) : "Not saved");

// Blank-preserving draft coercion (same rule as the cabinet panel): a blank
// draft stays blank, a numeric draft becomes a number, and a malformed draft
// is stored verbatim so the pricing diagnostics can flag it. The cell size is
// never defaulted here — the ported `|| 12` minted a guess on a missing value.
const landscapeInputValue = (value) =>
  value === "" ? "" : Number.isFinite(Number(value)) ? Number(value) : value;

export default function LandscapeDesigner({ landscape, onChange }) {
  const [brush, setBrush] = useState("grass");
  const [painting, setPainting] = useState(false);
  const cells = landscape?.cells || {};
  const summary = landscapeSummary(landscape);
  const broken = summary.issues.length > 0;
  const cellSizeIssue = summary.issues.some((i) => i.field === "cell_size_inches");

  const paint = (x, y) => {
    const key = `${x},${y}`;
    const next = { ...cells };
    if (brush === "dirt") delete next[key];
    else next[key] = brush;
    // Preserve the authored cell size verbatim — never mint a guessed 12 over
    // a missing value; an absent/malformed size stays flagged until recorded.
    onChange({ cell_size_inches: landscape?.cell_size_inches, cells: next });
  };

  return (
    <div className={`bg-white rounded-sm border p-3 ${broken ? "border-amber-300" : "border-gray-200"}`}>
      <div className="flex items-center justify-between mb-2">
        <div>
          <h3 className="text-[13px] font-bold text-gray-900">Landscape Designer</h3>
          <p className="text-[11px] text-gray-400">
            Draw landscaping features, paths and site boundaries. Each cell is 1 sq ft.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <label className="text-[10px] text-gray-500">
            Cell size (in)
            <input
              type="number"
              min={0}
              step="any"
              data-landscape-field="cell_size_inches"
              value={landscape?.cell_size_inches ?? ""}
              aria-invalid={cellSizeIssue || undefined}
              aria-describedby={cellSizeIssue ? "landscape-pricing" : undefined}
              onChange={(e) => onChange({
                cell_size_inches: landscapeInputValue(e.target.value),
                cells,
              })}
              className={`ml-1 h-7 w-16 rounded-sm border px-1 text-[11px] ${cellSizeIssue ? "border-amber-400 bg-amber-50" : "border-gray-300"}`}
            />
          </label>
          <button type="button"
            onClick={() => {
              if (!window.confirm("Clear all landscaping from the canvas?")) return;
              onChange({ cell_size_inches: 12, cells: {} });
            }}
            className="h-[26px] px-2 flex items-center gap-1 rounded-sm border border-gray-300 text-[11px] text-gray-600 hover:bg-gray-50"
          >
            <Trash2 className="w-3 h-3" aria-hidden="true" /> Clear
          </button>
        </div>
      </div>

      {broken && (
        <ul role="status" id="landscape-pricing" className="list-disc pl-5 mb-2 text-[10px] text-amber-800">
          {summary.issues.map((i, k) => <li key={k}>{i.message}</li>)}
        </ul>
      )}

      <div className="flex gap-3 items-start">
        <div className="w-[120px] flex-shrink-0 space-y-1">
          <div className="text-[10px] font-bold uppercase tracking-wide text-gray-400">Materials</div>
          {LANDSCAPE_MATERIALS.map((m) => (
            <button type="button"
              key={m.key}
              onClick={() => setBrush(m.key)}
              className={`w-full flex items-center gap-2 px-2 py-1 rounded-sm border text-[11px] ${
                brush === m.key ? "border-red-400 bg-red-50 font-semibold" : "border-gray-200 hover:bg-gray-50"
              }`}
            >
              <span className="w-3 h-3 rounded-sm" style={{ background: m.color }} />
              <span className="truncate text-gray-700">{m.label}</span>
            </button>
          ))}
        </div>

        <div
          className="flex-1 overflow-auto rounded-sm border border-gray-300 bg-[#a1866f] p-1 select-none"
          onMouseLeave={() => setPainting(false)}
        >
          <div
            className="grid gap-px"
            style={{ gridTemplateColumns: `repeat(${GRID_COLS}, minmax(14px, 1fr))` }}
          >
            {Array.from({ length: GRID_ROWS }).map((_, y) =>
              Array.from({ length: GRID_COLS }).map((__, x) => {
                const key = cells[`${x},${y}`];
                const mat = key ? materialByKey(key) : null;
                return (
                  <div
                    key={`${x},${y}`}
                    onMouseDown={() => {
                      setPainting(true);
                      paint(x, y);
                    }}
                    onMouseEnter={() => painting && paint(x, y)}
                    onMouseUp={() => setPainting(false)}
                    className="aspect-square cursor-crosshair"
                    style={{ background: mat ? mat.color : "rgba(0,0,0,0.06)" }}
                  />
                );
              })
            )}
          </div>
        </div>
      </div>

      {summary.lines.length > 0 && (
        <div className="mt-3 border-t border-gray-100 pt-2 space-y-1">
          {summary.lines.map((l) => (
            <div key={l.key} className="flex items-center gap-2 text-[11px] text-gray-600">
              <span className="w-2.5 h-2.5 rounded-sm" style={{ background: l.color }} />
              <span className="flex-1">{l.label}</span>
              <span>{sqftLabel(l)}</span>
              <span className="w-16 text-right font-semibold text-gray-800">{costLabel(l.cost)}</span>
            </div>
          ))}
          <div className="flex justify-between text-[12px] font-bold text-gray-900 pt-1">
            <span>Landscape total</span>
            <span className={Number.isFinite(summary.total) ? "" : "text-amber-700"}>{costLabel(summary.total)}</span>
          </div>
        </div>
      )}
    </div>
  );
}

import { useId, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Undo2, Trash2, Square } from "lucide-react";
import { foundationWallOutlineBasis, foundationWallRectangle, foundationWallSegments } from "./wallCalculator";

// Wall footprint in inches. Shape (matches SignEstimate Pro):
//   { points: [{x, z}], closed: bool, segments: [{ length }] }
const PX_PER_IN = 1.4; // canvas scale
const SNAP = 2; // snap to 2"

export function buildSegments(points, closed) {
  return foundationWallSegments(points, closed);
}

const shapeRecord = (current) =>
  current && typeof current === "object" && !Array.isArray(current) ? current : {};

const emitShape = (current, points, closed) => {
  const segments = foundationWallSegments(points, closed);
  if (!segments) return null;
  return { ...shapeRecord(current), points, closed, segments };
};

export default function WallShapeEditor({ shape, onChange }) {
  const basis = foundationWallOutlineBasis(shape);
  const points = basis.points;
  const closed = basis.closed;
  const [rect, setRect] = useState({ l: 96, w: 48 });
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const gridId = `wallGrid-${uid}`;
  const rectLId = `rectL-${uid}`;
  const rectWId = `rectW-${uid}`;
  const rectErrId = `rect-err-${uid}`;

  const W = 520;
  const H = 300;
  const toPx = (p) => ({ x: p.x * PX_PER_IN + 20, y: p.z * PX_PER_IN + 20 });

  const addPoint = (e) => {
    if (closed) return;
    const box = e.currentTarget.getBoundingClientRect();
    const sx = (e.clientX - box.left) * (W / box.width);
    const sy = (e.clientY - box.top) * (H / box.height);
    const x = Math.max(0, Math.round((sx - 20) / PX_PER_IN / SNAP) * SNAP);
    const z = Math.max(0, Math.round((sy - 20) / PX_PER_IN / SNAP) * SNAP);
    if (!Number.isFinite(x) || !Number.isFinite(z)) return;
    const last = points[points.length - 1];
    if (last && last.x === x && last.z === z) return;
    const next = emitShape(shape, [...points, { x, z }], false);
    if (next) onChange(next);
  };

  const rectShape = foundationWallRectangle(rect.l, rect.w);
  const rectLBad = foundationWallRectangle(rect.l, 1) === null;
  const rectWBad = foundationWallRectangle(1, rect.w) === null;
  const setRectangle = () => {
    if (!rectShape) return;
    onChange({ ...shapeRecord(shape), ...rectShape });
  };

  const segments = Array.isArray(shape?.segments) ? shape.segments : [];
  const hasSegmentLengths = segments.length > 0;
  const legacyOnly = !basis.hasRecordedPoints && hasSegmentLengths;
  const malformedPoints = basis.hasRecordedPoints && !points.length;
  const clearable = points.length > 0 || hasSegmentLengths || shape?.points != null || shape?.segments != null;
  const perimeter = basis.perimeterInches;
  const emit = (pointsNext, closedNext) => {
    const next = emitShape(shape, pointsNext, closedNext);
    if (next) onChange(next);
  };

  return (
    <div className="space-y-2">
      <div className="flex flex-wrap items-end gap-2">
        <label className="text-xs text-gray-500">
          Rect L (in)
          <Input
            type="number"
            step="any"
            className="w-24"
            value={rect.l}
            id={rectLId}
            aria-invalid={rectLBad || undefined}
            aria-describedby={rectLBad ? rectErrId : undefined}
            onChange={(e) => setRect({ ...rect, l: e.target.value })}
          />
        </label>
        <label className="text-xs text-gray-500">
          Rect W (in)
          <Input
            type="number"
            step="any"
            className="w-24"
            value={rect.w}
            id={rectWId}
            aria-invalid={rectWBad || undefined}
            aria-describedby={rectWBad ? rectErrId : undefined}
            onChange={(e) => setRect({ ...rect, w: e.target.value })}
          />
        </label>
        <Button variant="outline" size="sm" onClick={setRectangle} disabled={!rectShape}
          aria-describedby={!rectShape ? rectErrId : undefined}>
          <Square className="w-4 h-4" aria-hidden="true" /> Use rectangle
        </Button>
        {!rectShape && (
          <span role="status" id={rectErrId} className="text-xs text-amber-600">
            Rectangle dimensions must be positive finite inches; current outline is unchanged.
          </span>
        )}
        <Button
          variant="outline"
          size="sm"
          disabled={points.length < 3 || closed}
          onClick={() => emit(points, true)}
        >
          Close outline
        </Button>
        <Button
          variant="ghost"
          size="sm"
          disabled={!points.length}
          onClick={() => emit(points.slice(0, -1), false)}
        >
          <Undo2 className="w-4 h-4" aria-hidden="true" /> Undo
        </Button>
        <Button
          variant="ghost"
          size="sm"
          disabled={!clearable}
          onClick={() => {
            if (!window.confirm("Clear the drawn outline?")) return;
            onChange({ ...shapeRecord(shape), points: [], closed: false, segments: [] });
          }}
        >
          <Trash2 className="w-4 h-4 text-red-500" aria-hidden="true" /> Clear
        </Button>
      </div>

      <svg
        width="100%"
        viewBox={`0 0 ${W} ${H}`}
        onClick={addPoint}
        className="rounded-lg border border-gray-200 bg-slate-50"
        style={{ cursor: closed ? "default" : "crosshair" }}
      >
        <defs>
          <pattern id={gridId} width={12 * PX_PER_IN} height={12 * PX_PER_IN} patternUnits="userSpaceOnUse">
            <path d={`M ${12 * PX_PER_IN} 0 L 0 0 0 ${12 * PX_PER_IN}`} fill="none" stroke="#e2e8f0" strokeWidth="1" />
          </pattern>
        </defs>
        <rect width={W} height={H} fill={`url(#${gridId})`} />

        {points.length > 1 && (
          <polyline
            points={[...points, ...(closed ? [points[0]] : [])].map((p) => {
              const q = toPx(p);
              return `${q.x},${q.y}`;
            }).join(" ")}
            fill={closed ? "rgba(248,113,113,0.12)" : "none"}
            stroke="#ef4444"
            strokeWidth="3"
          />
        )}

        {points.map((p, i) => {
          const q = toPx(p);
          return <circle key={i} cx={q.x} cy={q.y} r="5" fill="#fff" stroke="#ef4444" strokeWidth="2" />;
        })}

        {points.length === 0 && (
          <text x="20" y="28" fontSize="12" fill="#94a3b8">
            Click to place footprint corners, or enter a rectangle above.
          </text>
        )}
      </svg>

      <div className="text-xs text-gray-600">
        {hasSegmentLengths ? `${segments.length} segment${segments.length === 1 ? "" : "s"}` : "no segments"} · perimeter{" "}
        <span className="font-semibold text-gray-900">{perimeter === null ? "Unavailable" : `${Math.round(perimeter)}"`}</span>
        {closed ? " · closed" : points.length > 2 ? " · open (close it for an internal fill wall)" : ""}
      </div>
      {legacyOnly && (
        <div role="status" className="text-xs text-amber-600">
          Recorded segment lengths only — no drawable footprint. Draw or enter a rectangle to re-establish geometry.
        </div>
      )}
      {malformedPoints && (
        <div role="status" className="text-xs text-amber-600">
          Recorded footprint coordinates need repair before a preview can be drawn.
        </div>
      )}
    </div>
  );
}

import { staffEntities } from "@/components/staff/staffEntities";
import { ensureIdempotentEntityCreate, newCreationRequestKey } from "@/components/estimator/idempotentEntityCreate";

// Convert a Foundation project into a Brick & Stone draft (#77). Carries the
// shared identity fields; geometry/materials stay at module defaults for
// recalc, and the Foundation source is never modified. The optional
// attemptRef holds a signature-stable creation_request_key so a double-click
// or a lost response reuses the same draft instead of creating duplicates.
export async function convertFoundationToBrickStone({ project, attemptRef } = {}) {
  if (!project?.id) throw new Error("Save the Foundation project before converting.");
  const sourceName = String(project.project_name || "Foundation").trim();
  const payload = {
    project_name: `${sourceName} (Brick & Stone)`,
    client_name: String(project.client_name || "").trim(),
    customer_id: String(project.customer_id || "").trim() || undefined,
    estimate_number: String(project.estimate_number || "").trim() || undefined,
    hyperlink: String(project.hyperlink || "").trim() || undefined,
    status: "draft",
    notes: `Converted from Foundation project "${sourceName}" (${project.id}). Re-enter masonry dimensions to calculate.`,
  };
  const signature = JSON.stringify(payload);
  if (attemptRef && attemptRef.current?.signature !== signature) {
    attemptRef.current = { signature, key: newCreationRequestKey("foundation_to_brick_stone") };
  }
  const key = attemptRef?.current?.key || newCreationRequestKey("foundation_to_brick_stone");
  const created = await ensureIdempotentEntityCreate({
    entity: staffEntities.BrickStoneProject,
    keyField: "creation_request_key",
    key,
    data: payload,
    label: "Brick & Stone draft",
  });
  if (!created?.id) throw new Error("Brick & Stone draft could not be verified.");
  return created;
}

import React, { useEffect, useMemo, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import { TrendingUp, Info } from "lucide-react";
import { applyMarkups, parseVolumeDiscountBrackets, parseVolumeDiscountCategories } from "./markupEngine";
import { loadCustomerPricingConfig } from "./savedCustomerPricing";
import TierBadge, { getTierTheme } from "./TierBadge";

const fmt = (n) => "$" + (Number(n) || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

/**
 * Reusable Customer Pricing Summary tab for every estimator.
 *
 * Props:
 *   project      — the in-memory project object with totals
 *   categorize   — function(project) => [{ module, label, cost, category_key }]
 *   accentColor  — tailwind color name (purple, red, green, blue, orange) for the header
 *   onTierChange — optional callback. When provided, selected tier becomes the Builder's saved tier on next save.
 *   onApplyTier  — optional explicit-apply callback for Builders that already have a working manual pricing mode.
 */
export default function CustomerPricingTab({ project, categorize, accentColor = "slate", onTierChange, onApplyTier }) {
  const [tiers, setTiers] = useState([]);
  const [categories, setCategories] = useState([]);
  const [settings, setSettings] = useState([]);
  const [tierNumber, setTierNumber] = useState(1);
  const [customerDefaultTier, setCustomerDefaultTier] = useState(1);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState("");

  useEffect(() => {
    let active = true;
    (async () => {
      if (active) {
        setLoading(true);
        setLoadError("");
      }
      try {
        const config = await loadCustomerPricingConfig(project);
        if (!active) return;
        setTiers(config.tiers || []);
        setCategories(config.categories || []);
        setSettings(config.settings || []);
        setCustomerDefaultTier(Number(config.customer?.pricing_tier) || 1);
        setTierNumber(Number(config.defaultTierNumber) || 1);
      } catch (e) {
        console.error("CustomerPricingTab load error:", e);
        if (active) setLoadError(e?.message || "Customer pricing configuration could not be verified.");
      }
      if (active) setLoading(false);
    })();
    return () => { active = false; };
  }, [project?.customer_id]);

  useEffect(() => {
    const savedTier = Number(project?.customer_pricing?.tier_number || project?.customer_pricing_tier);
    if (savedTier > 0 && tiers.some((tier) => Number(tier.tier_number) === savedTier)) {
      setTierNumber(savedTier);
    }
  }, [project?.customer_pricing?.tier_number, project?.customer_pricing_tier, tiers]);

  const selectedTier = useMemo(
    () => tiers.find((t) => t.tier_number === Number(tierNumber)) || tiers[0],
    [tiers, tierNumber]
  );

  const lines = useMemo(() => {
    try {
      return categorize(project) || [];
    } catch (e) {
      console.error("categorize error:", e);
      return [];
    }
  }, [project, categorize]);

  const markupResult = useMemo(() => {
    const brackets = parseVolumeDiscountBrackets(settings);
    const eligibleCategoryKeys = parseVolumeDiscountCategories(settings);
    const categoryFlags = Object.fromEntries(
      (categories || []).map((c) => [c?.category_key, c?.volume_discount_eligible]).filter(([k]) => k),
    );
    return applyMarkups(lines, selectedTier, { brackets, eligibleCategoryKeys, categoryFlags });
  }, [lines, selectedTier, settings, categories]);

  const categoryNameByKey = useMemo(
    () => Object.fromEntries(categories.map((c) => [c.category_key, c.category_name])),
    [categories]
  );

  // Group lines by category for display
  const byCategory = useMemo(() => {
    const map = {};
    markupResult.lines.forEach((l) => {
      const key = l.category_key;
      if (!map[key]) {
        map[key] = { name: categoryNameByKey[key] || key, lines: [], rawTotal: 0, finalTotal: 0 };
      }
      map[key].lines.push(l);
      map[key].rawTotal += l.cost;
      map[key].finalTotal += l.final_cost;
    });
    return map;
  }, [markupResult, categoryNameByKey]);

  const theme = getTierTheme(tierNumber);

  if (loading) {
    return (
      <Card className="bg-white border-0 shadow-sm">
        <CardContent className="p-8 text-center text-slate-500">Loading pricing tiers…</CardContent>
      </Card>
    );
  }

  if (loadError) {
    return (
      <Card className="bg-red-50 border-red-200">
        <CardContent className="p-6 text-sm text-red-900">
          <div className="flex items-start gap-2">
            <Info className="w-4 h-4 mt-0.5 flex-shrink-0" />
            <div>
              <p className="font-medium mb-1">Customer pricing unavailable</p>
              <p className="text-xs">{loadError}</p>
              <p className="text-xs mt-1">Tier-based customer pricing is not treated as missing or recalculated from fallback configuration while these pricing records cannot be verified.</p>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (tiers.length === 0) {
    return (
      <Card className="bg-amber-50 border-amber-200">
        <CardContent className="p-6 text-sm text-amber-900">
          <div className="flex items-start gap-2">
            <Info className="w-4 h-4 mt-0.5 flex-shrink-0" />
            <div>
              <p className="font-medium mb-1">No pricing tiers configured</p>
              <p className="text-xs">
                Visit <span className="font-semibold">Admin → Markups</span> to set up tier markups before using this view.
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (lines.length === 0) {
    return (
      <Card className="bg-white border-0 shadow-sm">
        <CardContent className="p-8 text-center text-slate-500 text-sm">
          Add items to the project to see customer pricing.
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      {/* Tier selector */}
      <Card className="bg-white border-0 shadow-sm">
        <CardHeader className="pb-3">
          <CardTitle className="text-lg flex items-center gap-2">
            <TrendingUp className={`w-5 h-5 text-${accentColor}-600`} />
            Customer Pricing Summary
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="flex flex-wrap items-end gap-4">
            <div className="min-w-[260px] flex-1">
              <Label className="text-xs mb-1.5 block">Pricing Tier</Label>
              <Select
                value={String(tierNumber)}
                onValueChange={(v) => {
                  const nextTier = Number(v);
                  setTierNumber(nextTier);
                  onTierChange?.(nextTier);
                }}
              >
                <SelectTrigger className="h-10">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {tiers.map((t) => (
                    <SelectItem key={t.id} value={String(t.tier_number)}>
                      Tier {t.tier_number} — {t.tier_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className={`flex items-center gap-3 px-4 py-2 rounded-xl ${theme.soft} ${theme.softText} border ${theme.accent}`}>
              <TierBadge tierNumber={tierNumber} />
              <div>
                <p className="text-xs opacity-75">Selected Tier</p>
                <p className="font-semibold text-sm">{selectedTier?.tier_name || `Tier ${tierNumber}`}</p>
              </div>
              {onApplyTier && (
                <button
                  type="button"
                  onClick={() => onApplyTier(tierNumber)}
                  className="ml-auto h-8 px-3 rounded border border-current/25 bg-white/80 text-xs font-semibold hover:bg-white"
                >
                  Use Tier {tierNumber}
                </button>
              )}
            </div>
          </div>
          {selectedTier?.description && (
            <p className="text-xs text-slate-500 italic">{selectedTier.description}</p>
          )}
        </CardContent>
      </Card>

      {/* Cost breakdown by category */}
      <Card className="bg-white border-0 shadow-sm">
        <CardHeader className="pb-3">
          <CardTitle className="text-base">Marked-Up Breakdown by Category</CardTitle>
        </CardHeader>
        <CardContent className="overflow-x-auto p-0">
          <table className="w-full text-sm">
            <thead className="bg-slate-50 text-slate-600 text-xs">
              <tr>
                <th className="text-left px-4 py-2 font-medium">Description</th>
                <th className="text-right px-4 py-2 font-medium">Cost</th>
                <th className="text-right px-4 py-2 font-medium">Markup</th>
                <th className="text-right px-4 py-2 font-medium">Vol Disc</th>
                <th className="text-right px-4 py-2 font-medium">Customer Price</th>
              </tr>
            </thead>
            <tbody>
              {Object.entries(byCategory).map(([catKey, group]) => (
                <React.Fragment key={catKey}>
                  <tr className="bg-slate-100/70">
                    <td colSpan={5} className="px-4 py-2 font-semibold text-slate-700 text-xs uppercase tracking-wide">
                      {group.name}
                      <span className="ml-2 text-slate-500 font-normal normal-case tracking-normal">
                        — {fmt(group.rawTotal)} cost → <span className="font-semibold text-slate-700">{fmt(group.finalTotal)}</span>
                      </span>
                    </td>
                  </tr>
                  {group.lines.map((l, i) => (
                    <tr key={`${catKey}-${i}`} className="border-t border-slate-100 hover:bg-slate-50/50">
                      <td className="px-4 py-2">{l.label}</td>
                      <td className="px-4 py-2 text-right tabular-nums text-slate-500">{fmt(l.cost)}</td>
                      <td className="px-4 py-2 text-right tabular-nums">
                        {(l.markup_multiplier * 100).toFixed(1)}%
                      </td>
                      <td className="px-4 py-2 text-right tabular-nums">
                        {l.volume_discount_applied > 0 ? `${l.volume_discount_applied}%` : "—"}
                      </td>
                      <td className="px-4 py-2 text-right tabular-nums font-semibold">{fmt(l.final_cost)}</td>
                    </tr>
                  ))}
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </CardContent>
      </Card>

      {/* Grand total card */}
      <Card className={`border-2 ${theme.accent} ${theme.soft}`}>
        <CardContent className="p-5 space-y-2">
          <div className="flex justify-between text-sm text-slate-600">
            <span>Internal cost subtotal</span>
            <span className="tabular-nums">{fmt(markupResult.totals.raw_subtotal)}</span>
          </div>
          <div className="flex justify-between text-sm text-slate-600">
            <span>After Tier {tierNumber} markup</span>
            <span className="tabular-nums">{fmt(markupResult.totals.marked_subtotal)}</span>
          </div>
          {markupResult.totals.volume_discount_pct > 0 && (
            <div className="flex justify-between text-sm text-amber-700">
              <span>Volume discount ({markupResult.totals.volume_discount_pct}%)</span>
              <span className="tabular-nums">
                −{fmt(markupResult.totals.marked_subtotal - markupResult.totals.grand_total)}
              </span>
            </div>
          )}
          <div className={`border-t pt-2 flex justify-between items-center ${theme.softText}`}>
            <span className="text-lg font-bold">Customer Price</span>
            <span className="text-2xl font-bold tabular-nums">{fmt(markupResult.totals.grand_total)}</span>
          </div>
          {markupResult.totals.raw_subtotal > 0 && (
            <p className="text-xs text-slate-500 pt-1">
              Margin: <span className="font-semibold">{fmt(markupResult.totals.grand_total - markupResult.totals.raw_subtotal)}</span>
              {" "}({(((markupResult.totals.grand_total - markupResult.totals.raw_subtotal) / markupResult.totals.grand_total) * 100).toFixed(1)}% of customer price)
            </p>
          )}
        </CardContent>
      </Card>

      <Card className="bg-blue-50 border-blue-200">
        <CardContent className="p-3 text-xs text-blue-900 flex items-start gap-2">
          <Info className="w-4 h-4 flex-shrink-0 mt-0.5" />
          <span>
            Markups and volume discount brackets are configured in <strong>Admin → Markups</strong>.
            {onTierChange ? (
              <> Tier {tierNumber} will be saved with this Builder the next time you save it. Customer default: Tier {customerDefaultTier}.</>
            ) : onApplyTier ? (
              <> Preview tiers freely, then choose <strong>Use Tier {tierNumber}</strong> to replace this Builder's manual sell-price mode. Customer default: Tier {customerDefaultTier}.</>
            ) : (
              <> This view is currently preview-only.</>
            )}
          </span>
        </CardContent>
      </Card>
    </div>
  );
}

import { base44 } from "@/api/base44Client";
import { applyMarkups, parseVolumeDiscountBrackets, parseVolumeDiscountCategories } from "./markupEngine";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";

const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;

function resolveTierNumber({ project, customer, requestedTierNumber, tiers }) {
  const candidates = [
    requestedTierNumber,
    project?.customer_pricing?.tier_number,
    project?.customer_pricing_tier,
    customer?.pricing_tier,
    1,
  ];
  for (const candidate of candidates) {
    const tierNumber = num(candidate, NaN);
    if (Number.isFinite(tierNumber) && (tiers || []).some((tier) => num(tier.tier_number) === tierNumber)) {
      return tierNumber;
    }
  }
  return num(tiers?.[0]?.tier_number, 1);
}

const isNotFoundError = (error) => Number(error?.response?.status || error?.status || error?.statusCode || 0) === 404;

export async function loadCustomerPricingConfig(project = {}) {
  try {
    const [tiers, categories, settings, customer] = await Promise.all([
      // Tier definitions and pricing Settings directly change customer selling
      // price, so a read failure must never masquerade as "not configured".
      loadAllEntityRows({ entity: base44.entities.MarkupTier, sort: "sort_order", label: "Customer pricing markup tiers" }),
      // Category records only provide display labels; pricing lines already carry
      // their category keys, so this metadata may remain non-blocking.
      loadAllEntityRows({ entity: base44.entities.MarkupCategory, sort: "sort_order", label: "Customer pricing markup categories" }).catch(() => []),
      loadAllEntityRows({ entity: base44.entities.Settings, query: { category: "pricing" }, sort: null, label: "Customer pricing settings" }),
      project?.customer_id
        ? base44.entities.Customer.get(project.customer_id).catch((error) => {
            // Preserve legacy projects whose historical Customer record no longer
            // exists, but fail closed on permission/network/service read errors.
            if (isNotFoundError(error)) return null;
            throw error;
          })
        : Promise.resolve(null),
    ]);

    const defaultTierNumber = resolveTierNumber({ project, customer, tiers });
    return { tiers: tiers || [], categories: categories || [], settings: settings || [], customer, defaultTierNumber };
  } catch (error) {
    throw new Error(`Customer pricing configuration could not be verified: ${error?.message || "unknown read error"}`);
  }
}

export function calculateCustomerPricingFromConfig({ project, categorize, tierNumber, tiers = [], settings = [], customer = null, categories = [] }) {
  if (!project || typeof categorize !== "function" || !tiers.length) return null;
  const resolvedTierNumber = resolveTierNumber({ project, customer, requestedTierNumber: tierNumber, tiers });
  const selectedTier = tiers.find((tier) => num(tier.tier_number) === resolvedTierNumber) || tiers[0];
  const lines = categorize(project) || [];
  if (!selectedTier || !lines.length) return null;

  const categoryFlags = Object.fromEntries(
    (categories || []).map((c) => [c?.category_key, c?.volume_discount_eligible]).filter(([k]) => k),
  );
  const result = applyMarkups(lines, selectedTier, {
    brackets: parseVolumeDiscountBrackets(settings),
    eligibleCategoryKeys: parseVolumeDiscountCategories(settings),
    categoryFlags,
  });

  return {
    applied: true,
    tier_number: num(selectedTier.tier_number, resolvedTierNumber),
    tier_name: selectedTier.tier_name || `Tier ${resolvedTierNumber}`,
    tier_updated_date: String(selectedTier?.updated_date || ""),
    customer_default_tier: num(customer?.pricing_tier, 1),
    raw_subtotal: num(result?.totals?.raw_subtotal),
    marked_subtotal: num(result?.totals?.marked_subtotal),
    eligible_subtotal: num(result?.totals?.eligible_subtotal),
    volume_discount_pct: num(result?.totals?.volume_discount_pct),
    total: num(result?.totals?.grand_total),
    saved_at: new Date().toISOString(),
    lines: (result?.lines || []).map((line) => ({
      module: line.module || "",
      label: line.label || "",
      category_key: line.category_key || "",
      cost: num(line.cost),
      markup_multiplier: num(line.markup_multiplier, 1),
      marked_up_cost: num(line.marked_up_cost),
      volume_discount_applied: num(line.volume_discount_applied),
      final_cost: num(line.final_cost),
    })),
  };
}

export async function calculateSavedCustomerPricing({ project, categorize, tierNumber }) {
  const config = await loadCustomerPricingConfig(project);
  return calculateCustomerPricingFromConfig({
    project,
    categorize,
    tierNumber,
    tiers: config.tiers,
    settings: config.settings,
    customer: config.customer,
    categories: config.categories,
  });
}

// Extracts cost lines from each module's project records and tags them
// with the proper category_key for tier-markup application.
//
// Mapping (from user's tier sheet):
//   Channel/Raceway/Capsule letter purchases  -> outsourced_fab
//   Dimensional Letter substrate (material)   -> substrates
//   Dimensional Letter paint materials        -> outsourced_fab
//   Dimensional Letter fab labor (CNC+paint)  -> inhouse_labor
//   Channel Letter install labor              -> inhouse_labor
//   Install materials/supplies (hardware)     -> outsourced_fab
//   Equipment rental (lifts)                  -> outsourced_services
//   Concrete + rebar materials                -> outsourced_fab
//   Foundation labor                          -> inhouse_labor
//   Poles                                     -> outsourced_fab
//   Foundation equipment rental               -> outsourced_services
//   Brick/stone material                      -> outsourced_fab
//   Masonry outsourced labor                  -> outsourced_services
//   Mortar + supplies                         -> outsourced_fab
//   Paint Estimator materials                 -> outsourced_fab
//   Paint Estimator labor                     -> inhouse_labor
//   Laser machine time                        -> machine_time
//   Laser labor                               -> inhouse_labor
//   Laser materials                           -> substrates
//   CNC machine time                          -> machine_time
//   CNC labor                                 -> inhouse_labor
//   CNC materials                             -> substrates
//   Metal Fab material                        -> substrates
//   Metal Fab labor                           -> inhouse_labor

const num = (v) => Number(v) || 0;

// Per-project memoization (#412): categorize output depends only on the
// project payload. A WeakMap keyed on the project object skips recompute when
// React re-renders pass the same object, and entries GC with the object.
const _catCache = new WeakMap();
const _catMemo = (p, compute) => {
  if (!p || typeof p !== "object") return compute(p);
  let byFn = _catCache.get(p);
  if (byFn && byFn.has(compute)) return byFn.get(compute);
  const out = compute(p);
  if (!byFn) { byFn = new Map(); _catCache.set(p, byFn); }
  byFn.set(compute, out);
  return out;
};

function _impl_categorizeChannelLetterProject(p) {
  if (!p) return [];
  const lines = [];

  // 1. Letter purchases - check each letter type
  (p.letter_purchases || []).forEach((lp) => {
    const isDimensional = lp.letter_type === 'dimensional_letters';
    const total = num(lp.total_cost);
    if (total <= 0) return;

    if (isDimensional && lp.fab_config) {
      // Dimensional: split into material vs labor using fab_config if present
      const matCost = num(lp.fab_config.material_cost) + num(lp.fab_config.paint_material_cost);
      const laborCost = num(lp.fab_config.cnc_labor_cost) + num(lp.fab_config.paint_labor_cost);
      if (matCost > 0) {
        lines.push({ module: 'channel_letter', label: `Dimensional Letter Material — ${lp.description || ''}`, cost: matCost, category_key: 'substrates' });
      }
      if (laborCost > 0) {
        lines.push({ module: 'channel_letter', label: `Dimensional Letter Fab Labor — ${lp.description || ''}`, cost: laborCost, category_key: 'inhouse_labor' });
      }
      const remainder = total - matCost - laborCost;
      if (remainder > 0.01) {
        lines.push({ module: 'channel_letter', label: `Dimensional Letter (other) — ${lp.description || ''}`, cost: remainder, category_key: 'substrates' });
      }
    } else if (isDimensional) {
      // Dimensional with no fab_config breakdown — categorize whole as substrates (material side)
      lines.push({ module: 'channel_letter', label: `Dimensional Letters — ${lp.description || ''}`, cost: total, category_key: 'substrates' });
    } else {
      // Channel / Raceway / Capsule / Logo = outsourced fab
      lines.push({ module: 'channel_letter', label: `Letter Purchase — ${lp.description || lp.letter_type}`, cost: total, category_key: 'outsourced_fab' });
    }
  });

  // 1b. Letter-level fees
  // Delivery doesn't apply when every product is dimensional (matches lettersCalculator)
  const onlyDimensional = (p.letter_purchases || []).length > 0 &&
    (p.letter_purchases || []).every(lp => lp.letter_type === 'dimensional_letters');
  const letterFees =
    (onlyDimensional ? 0 : num(p.letters_delivery_fee)) + num(p.letters_design_fee) +
    num(p.letters_install_supplies_fee) + num(p.letters_permitting_fee) +
    num(p.letters_other_fee);
  if (letterFees > 0) {
    lines.push({ module: 'channel_letter', label: 'Letter Fees (delivery/design/permit/etc.)', cost: letterFees, category_key: 'outsourced_fab' });
  }

  // 2. Installation labor — when a crew is assigned, personnel pricing replaces
  // the flat-rate labor (labor_cost_in_subtotal = 0), so labor is never double-counted.
  const baseLabor = p.labor_cost_in_subtotal !== undefined
    ? num(p.labor_cost_in_subtotal)
    : num(p.labor_cost);
  const installLabor = baseLabor + num(p.total_personnel_cost);
  if (installLabor > 0) {
    lines.push({ module: 'channel_letter', label: 'Installation Labor', cost: installLabor, category_key: 'inhouse_labor' });
  }

  // 3. Materials/supplies (hardware, mounting)
  const matCost = num(p.total_materials_cost) + num(p.total_supplies_cost);
  if (matCost > 0) {
    lines.push({ module: 'channel_letter', label: 'Install Materials & Supplies', cost: matCost, category_key: 'outsourced_fab' });
  }

  // 4. Equipment rental
  const eqCost = num(p.total_equipment_cost);
  if (eqCost > 0) {
    lines.push({ module: 'channel_letter', label: 'Equipment Rental', cost: eqCost, category_key: 'outsourced_services' });
  }

  // 5. Travel — was previously missing, so categorized lines didn't sum to the subtotal
  const travelCost = num(p.total_travel_cost);
  if (travelCost > 0) {
    lines.push({ module: 'channel_letter', label: 'Travel & Fuel', cost: travelCost, category_key: 'outsourced_services' });
  }

  return lines;
}

function _impl_categorizeFoundationProject(p) {
  if (!p) return [];
  const lines = [];
  const concrete = num(p.total_concrete_cost) + num(p.total_rebar_cost) + num(p.total_forming_materials_cost);
  if (concrete > 0) lines.push({ module: 'foundation', label: 'Concrete / Rebar / Forming Materials', cost: concrete, category_key: 'outsourced_fab' });
  const fLabor = num(p.total_labor_cost) + num(p.total_excavation_cost);
  if (fLabor > 0) lines.push({ module: 'foundation', label: 'Foundation Labor', cost: fLabor, category_key: 'inhouse_labor' });
  const poles = num(p.total_pole_cost) + num(p.total_pole_painting_cost);
  if (poles > 0) lines.push({ module: 'foundation', label: 'Poles & Pole Painting', cost: poles, category_key: 'outsourced_fab' });
  const eq = num(p.total_equipment_cost);
  if (eq > 0) lines.push({ module: 'foundation', label: 'Foundation Equipment Rental', cost: eq, category_key: 'outsourced_services' });

  // Foundation wall totals already contain their material, mortar and labor. Use
  // the calculated wall rows directly so tier pricing neither double-counts the
  // aggregate brick/fill fields nor treats masonry labor as purchased material.
  const wallMaterial = (p.walls || []).reduce((sum, wall) => {
    const costs = wall?.calculatedCosts || {};
    return sum + num(costs.materialCost) + num(costs.mortarCost) + num(costs.internalMaterialCost) + num(costs.internalMortarCost);
  }, 0);
  const wallLabor = (p.walls || []).reduce((sum, wall) => {
    const costs = wall?.calculatedCosts || {};
    return sum + num(costs.laborCost) + num(costs.internalLaborCost);
  }, 0);
  if (wallMaterial > 0) lines.push({ module: 'foundation', label: 'Brick / Wall / Mortar Materials', cost: wallMaterial, category_key: 'outsourced_fab' });
  if (wallLabor > 0) lines.push({ module: 'foundation', label: 'Masonry Labor', cost: wallLabor, category_key: 'outsourced_services' });

  const wallCaps = num(p.total_wall_cap_cost);
  if (wallCaps > 0) lines.push({ module: 'foundation', label: 'Wall Cap Materials', cost: wallCaps, category_key: 'outsourced_fab' });
  const cabinets = num(p.total_signage_cabinet_cost);
  if (cabinets > 0) lines.push({ module: 'foundation', label: 'Purchased Signage Cabinets', cost: cabinets, category_key: 'outsourced_fab' });
  const landscape = num(p.total_landscape_cost);
  if (landscape > 0) lines.push({ module: 'foundation', label: 'Landscape / Site Materials', cost: landscape, category_key: 'outsourced_fab' });
  return lines;
}

function _impl_categorizePaintProject(p) {
  if (!p) return [];
  const lines = [];
  const mats = num(p.total_paint_mask_cost) + num(p.total_liquid_paint_and_supplies_cost);
  if (mats > 0) lines.push({ module: 'paint', label: 'Paint Materials & Supplies', cost: mats, category_key: 'outsourced_fab' });
  const labor = num(p.total_labor_cost);
  if (labor > 0) lines.push({ module: 'paint', label: 'Paint Labor', cost: labor, category_key: 'inhouse_labor' });
  return lines;
}

function _impl_categorizeLaserProject(p) {
  if (!p) return [];
  const lines = [];
  const machine = num(p.total_machine_cost);
  if (machine > 0) lines.push({ module: 'laser', label: 'Laser Machine Time', cost: machine, category_key: 'machine_time' });
  const labor = num(p.total_labor_cost);
  if (labor > 0) lines.push({ module: 'laser', label: 'Laser Labor', cost: labor, category_key: 'inhouse_labor' });
  const supplies = num(p.total_supplies_cost);
  if (supplies > 0) lines.push({ module: 'laser', label: 'Laser Materials', cost: supplies, category_key: 'substrates' });
  return lines;
}

function _impl_categorizeCNCProject(p) {
  if (!p) return [];
  const lines = [];
  const machine = num(p.total_machine_cost);
  if (machine > 0) lines.push({ module: 'cnc', label: 'CNC Machine Time', cost: machine, category_key: 'machine_time' });
  const labor = num(p.total_labor_cost);
  if (labor > 0) lines.push({ module: 'cnc', label: 'CNC Labor', cost: labor, category_key: 'inhouse_labor' });
  return lines;
}

function _impl_categorizeMetalProject(p) {
  if (!p) return [];
  const lines = [];
  const mat = num(p.total_material_cost) + num(p.total_supplies_cost);
  if (mat > 0) lines.push({ module: 'metal', label: 'Metal Fab Material', cost: mat, category_key: 'substrates' });
  const labor = num(p.total_fabrication_cost) + num(p.total_welding_cost) + num(p.total_finishing_cost);
  if (labor > 0) lines.push({ module: 'metal', label: 'Metal Fab Labor', cost: labor, category_key: 'inhouse_labor' });
  return lines;
}

function _impl_categorizeBrickStoneProject(p) {
  if (!p) return [];
  const lines = [];
  const materials = num(p.material_cost) + num(p.mortar_cost);
  if (materials > 0) lines.push({ module: 'brick_stone', label: 'Brick / Stone / Mortar Materials', cost: materials, category_key: 'outsourced_fab' });
  const labor = num(p.labor_cost);
  if (labor > 0) lines.push({ module: 'brick_stone', label: 'Masonry Labor', cost: labor, category_key: 'outsourced_services' });
  return lines;
}

function _impl_categorizeMaintenanceProject(p) {
  if (!p) return [];
  const lines = [];
  const labor = num(p.labor_cost) + num(p.total_personnel_cost);
  if (labor > 0) lines.push({ module: 'maintenance', label: 'Maintenance Labor', cost: labor, category_key: 'inhouse_labor' });
  const materials = num(p.total_materials_cost) + num(p.total_supplies_cost);
  if (materials > 0) lines.push({ module: 'maintenance', label: 'Maintenance Materials & Supplies', cost: materials, category_key: 'outsourced_fab' });
  const services = num(p.total_equipment_cost) + num(p.total_travel_cost);
  if (services > 0) lines.push({ module: 'maintenance', label: 'Equipment & Travel', cost: services, category_key: 'outsourced_services' });
  return lines;
}

// Vinyl Estimator:
//   Vinyl + Laminate + Transfer Tape rolls + Ink + Blade → substrates
//   Machine time (printer / cutter / laminator amortized $/hr) → machine_time
//   Operator + Designer + Installer labor → inhouse_labor
//   Install equipment rental (lifts) → outsourced_services
//   Travel → outsourced_services
function _impl_categorizeVinylProject(p) {
  if (!p) return [];
  const lines = [];
  const materials =
    num(p.total_vinyl_cost) + num(p.total_laminate_cost) +
    num(p.total_ink_cost) + num(p.total_blade_cost) +
    num(p.total_supplies_cost);
  if (materials > 0) lines.push({ module: 'vinyl', label: 'Vinyl, Laminate, Tape, Ink & Supplies', cost: materials, category_key: 'substrates' });

  const machine = num(p.total_machine_cost);
  if (machine > 0) lines.push({ module: 'vinyl', label: 'Printer / Cutter / Laminator Time', cost: machine, category_key: 'machine_time' });

  const labor = num(p.labor_cost) + num(p.total_personnel_cost);
  if (labor > 0) lines.push({ module: 'vinyl', label: 'Production & Install Labor', cost: labor, category_key: 'inhouse_labor' });

  const equip = num(p.total_equipment_cost);
  if (equip > 0) lines.push({ module: 'vinyl', label: 'Install Equipment', cost: equip, category_key: 'outsourced_services' });

  const travel = num(p.total_travel_cost);
  if (travel > 0) lines.push({ module: 'vinyl', label: 'Travel', cost: travel, category_key: 'outsourced_services' });

  return lines;
}

