const num = (value, fallback = 0) =>
  Number.isFinite(Number(value)) ? Number(value) : fallback;

const nowIso = () => new Date().toISOString();

export const makeStableId = (prefix = "id") => {
  const uuid = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `${prefix}-${uuid}`;
};

function stripSystemFields(value) {
  if (Array.isArray(value)) return value.map(stripSystemFields);
  if (!value || typeof value !== "object") return value;
  const result = {};
  Object.keys(value)
    .sort()
    .forEach((key) => {
      if (["created_by", "created_by_id"].includes(key)) return;
      result[key] = stripSystemFields(value[key]);
    });
  return result;
}

export function stableStringify(value) {
  return JSON.stringify(stripSystemFields(value ?? null));
}

export function snapshotHash(value) {
  const text = stableStringify(value);
  let hash = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return `fnv1a-${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

export async function getSourceProject(line) {
  const mod = getModule(line?.module_key);
  if (!mod || !line?.project_id) return null;
  return staffEntities[mod.entity].get(line.project_id).catch(() => null);
}

export function sourceProjectTotal(line, record) {
  if (!record) return num(line?.live_total_snapshot, num(line?.total_snapshot));
  const totalField = MODULE_TOTAL_FIELD[line?.module_key];
  if (totalField) return num(record[totalField]);

  if (line?.module_key === "painting") {
    return num(record.total_paint_mask_cost)
      + num(record.total_liquid_paint_and_supplies_cost)
      + num(record.total_labor_cost);
  }

  if (line?.module_key === "foundation") {
    const direct = num(record.grand_total, NaN);
    if (Number.isFinite(direct)) return direct;
    const known = [
      "total_concrete_cost",
      "total_rebar_cost",
      "total_excavation_cost",
      "total_forming_materials_cost",
      "total_labor_cost",
      "total_wall_cost",
      "total_pole_cost",
      "total_pole_painting_cost",
      "total_equipment_cost",
      "total_wall_cap_cost",
      "total_signage_cabinet_cost",
      "total_landscape_cost",
    ];
    return known.reduce((sum, key) => sum + num(record[key]), 0);
  }

  return num(record.total_cost, num(line?.total_snapshot));
}

async function findBuilderProduct(line, estimateId) {
  if (line?.builder_product_id) {
    const direct = await staffEntities.BuilderProduct.get(line.builder_product_id).catch(() => null);
    if (direct) return direct;
  }

  if (line?.project_id) {
    const bySource = await staffEntities.BuilderProduct.filter({
      estimate_id: estimateId,
      source_project_id: line.project_id,
    });
    if (bySource?.[0]) return bySource[0];
  }

  if (line?.line_id) {
    const byLine = await staffEntities.BuilderProduct.filter({
      estimate_id: estimateId,
      estimate_line_id: line.line_id,
    });
    if (byLine?.[0]) return byLine[0];
  }

  return null;
}

function productIdentity(line) {
  const builderName = line?.builder_name || getModuleLabel(line?.module_key) || line?.project_name || "Product";
  const clientName = line?.client_product_name || line?.project_name || builderName;
  return { builderName, clientName };
}

const sameText = (a, b) => String(a ?? "") === String(b ?? "");
const sameNumber = (a, b) => Math.abs(num(a) - num(b)) <= 0.005;

function sameSubstantiveValue(a, b) {
  const bothPresent = a !== null && a !== undefined && a !== "" && b !== null && b !== undefined && b !== "";
  if (bothPresent && Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
    return sameNumber(a, b);
  }
  return stableStringify(a) === stableStringify(b);
}

function patchDiffers(record, patch) {
  return Object.entries(patch || {}).some(([key, value]) => !sameSubstantiveValue(record?.[key], value));
}

/**
 * Fully reconciled legacy Products are immutable at their frozen pricing layer.
 * Re-opening an estimate should not rewrite BuilderProduct/BuilderPart/Estimate
 * records merely to refresh timestamps. Reuse the existing linked state when the
 * source record has not changed and the persisted line already mirrors the
 * BuilderProduct. A real source update still falls through to normal recalculation.
 */
export function canReuseReconciledLegacyBuilder({
  line,
  builderProduct,
  source,
  lineId,
  sourceEntity,
  builderName,
  clientName,
}) {
  if (
    !line?.builder_product_id ||
    !builderProduct?.id ||
    line.builder_product_id !== builderProduct.id ||
    builderProduct.price_state !== "legacy_frozen" ||
    builderProduct.legacy_bom_reconciled !== true
  ) return false;

  const sourceStamp = String(source?.updated_date || "").trim();
  const recordedSourceStamp = String(
    line.updated_date_snapshot || builderProduct.builder_snapshot_source_updated_date || ""
  ).trim();
  if (sourceStamp && sourceStamp !== recordedSourceStamp) return false;

  const expectedCategory = line.product_category || builderProduct.product_category || "";
  const expectedProductionType = line.production_product_type ?? builderProduct.production_product_type ?? "";
  const expectedNotes = line.product_notes ?? builderProduct.product_notes ?? "";
  const expectedStatus = line.section_status === "complete" ? "complete" : "in_progress";

  return (
    sameText(builderProduct.estimate_line_id, lineId) &&
    sameText(builderProduct.module_key, line.module_key) &&
    sameText(builderProduct.source_entity, sourceEntity) &&
    sameText(builderProduct.source_project_id, line.project_id) &&
    sameText(builderProduct.builder_name, builderName) &&
    sameText(builderProduct.client_product_name, clientName) &&
    sameText(builderProduct.client_description, line.customer_description) &&
    sameText(builderProduct.product_category, expectedCategory) &&
    sameText(builderProduct.production_product_type, expectedProductionType) &&
    sameText(builderProduct.product_notes, expectedNotes) &&
    sameNumber(builderProduct.quantity, line.customer_quantity ?? 1) &&
    sameText(builderProduct.status, expectedStatus) &&
    sameNumber(line.total_snapshot, builderProduct.frozen_cost) &&
    sameNumber(line.live_total_snapshot, builderProduct.current_recalculated_cost) &&
    sameText(line.price_state, builderProduct.price_state) &&
    sameNumber(line.detached_part_count, builderProduct.detached_part_count) &&
    !!line.needs_reattach_review === !!builderProduct.needs_reattach_review
  );
}

export async function ensureBuilderProductForLine({ estimate, line, isNew = false, deferPartSync = false, strictPartSync = false, skipUnchangedWrites = false, sourceProjectOverride = undefined }) {
  const estimateId = estimate?.id;
  if (!estimateId || !line) return { line, builderProduct: null, changed: false };

  // A Builder mutation may be between durable steps. Preserve the exact saved
  // line and Builder state until that operation is explicitly resumed; page-open
  // reconciliation must never rewrite its recovery inputs. Quick Product insertion
  // has an initial provisional stage before its BuilderProduct exists.
  if (line?.price_acceptance_pending?.key) {
    if (line.price_acceptance_pending.kind === "builder_product_remove") {
      // Product removal intentionally deletes Builder/source records before the
      // final Estimate-line removal. Preserve the durable marker even when those
      // records are already gone so the user can safely resume cleanup.
      const pendingBuilder = line.builder_product_id
        ? await staffEntities.BuilderProduct.get(line.builder_product_id).catch(() => null)
        : null;
      if (pendingBuilder?.estimate_id && pendingBuilder.estimate_id !== estimateId) {
        throw new Error("A pending Product removal found a Builder Product owned by another estimate. The saved recovery marker was retained.");
      }
      return { line, builderProduct: pendingBuilder, changed: false, partSyncInputs: null };
    }
    if (!line.builder_product_id && ["builder_quick_product_insert", "builder_blank_product_insert"].includes(line.price_acceptance_pending.kind)) {
      return { line, builderProduct: null, changed: false, partSyncInputs: null };
    }
    if (line.builder_product_id) {
      const pendingBuilder = await staffEntities.BuilderProduct.get(line.builder_product_id);
      if (!pendingBuilder?.id || (pendingBuilder.estimate_id && pendingBuilder.estimate_id !== estimateId)) {
        throw new Error("A pending Builder mutation could not verify its Builder Product. The saved recovery marker was retained.");
      }
      return { line, builderProduct: pendingBuilder, changed: false, partSyncInputs: null };
    }
  }

  const lineId = line.line_id || makeStableId("line");
  const source = sourceProjectOverride !== undefined ? sourceProjectOverride : await getSourceProject(line);
  const sourceTotal = sourceProjectTotal(line, source);
  const acceptedTotal = num(line.total_snapshot);
  const acceptedCustomerPrice = acceptedCustomerUnitPrice(line);
  const { builderName, clientName } = productIdentity(line);
  const sourceEntity = getModule(line.module_key)?.entity || "";
  const timestamp = nowIso();
  let builderProduct = await findBuilderProduct(line, estimateId);
  if (!isNew && canReuseReconciledLegacyBuilder({
    line,
    builderProduct,
    source,
    lineId,
    sourceEntity,
    builderName,
    clientName,
  })) {
    const partSyncInputs = deferPartSync && source
      ? await loadVerifiedBuilderPartSyncInputs({ builderProduct, moduleKey: line.module_key })
      : null;
    return { line, builderProduct, changed: false, partSyncInputs };
  }
  const preserveLegacyEconomics = !isNew && (!builderProduct || builderProduct.price_state === "legacy_frozen");
  const economics = preserveLegacyEconomics
    ? { internalCost: sourceTotal, customerPrice: liveCustomerUnitPrice(line) }
    : sourceProjectEconomics(line.module_key, source, sourceTotal);
  const liveTotal = economics.internalCost;
  const liveCustomerPrice = economics.customerPrice;
  const partSyncInputs = (deferPartSync || strictPartSync) && source
    ? await loadVerifiedBuilderPartSyncInputs({ builderProduct, moduleKey: line.module_key })
    : null;

  if (!builderProduct) {
    const builderProductData = {
      estimate_id: estimateId,
      estimate_line_id: lineId,
      module_key: line.module_key,
      source_entity: sourceEntity,
      source_project_id: line.project_id || "",
      builder_name: builderName,
      client_product_name: clientName,
      client_description: line.customer_description || "",
      product_category: line.product_category || "",
      production_product_type: line.production_product_type || "",
      product_notes: line.product_notes || "",
      quantity: num(line.customer_quantity, 1),
      status: line.section_status === "complete" ? "complete" : "in_progress",
      builder_version: 1,
      builder_snapshot: source || {},
      builder_snapshot_at: timestamp,
      builder_snapshot_source_updated_date: source?.updated_date || line.updated_date_snapshot || "",
      builder_snapshot_hash: snapshotHash(source || {}),
      frozen_cost: isNew ? 0 : acceptedTotal,
      frozen_customer_price: isNew ? 0 : acceptedCustomerPrice,
      current_recalculated_cost: liveTotal,
      price_state: isNew ? "unchecked" : "legacy_frozen",
      price_delta: isNew ? liveTotal : liveTotal - acceptedTotal,
      price_delta_percent: !isNew && acceptedTotal ? ((liveTotal - acceptedTotal) / acceptedTotal) * 100 : 0,
      price_recalc_required: false,
      price_recalc_reason: "",
      last_price_check_at: timestamp,
      part_count: 0,
      group_count: 0,
      detached_part_count: 0,
      needs_reattach_review: false,
      is_active: true,
      notes: isNew
        ? "Builder Product created with estimate product. First priced save creates the initial frozen revision."
        : "Backfilled from an existing estimate line. Existing total_snapshot remains the authoritative legacy frozen price.",
    };
    const createResult = await createBuilderProductWithRecovery({
      entity: staffEntities.BuilderProduct,
      data: builderProductData,
      label: `Builder Product “${clientName || builderName || lineId}”`,
    });
    builderProduct = createResult.record;
  } else {
    const frozen = num(builderProduct.frozen_cost, acceptedTotal);
    const frozenCustomer = hasNumericValue(builderProduct.frozen_customer_price)
      ? num(builderProduct.frozen_customer_price)
      : acceptedCustomerPrice;
    const awaitingInitialFreeze = builderProduct.price_state === "unchecked" && frozen === 0;
    const nextState = builderProduct.price_state === "legacy_frozen"
      ? "legacy_frozen"
      : awaitingInitialFreeze
        ? "unchecked"
        : builderProduct.price_state === "manual"
          ? manualCustomerPriceState({
              detached: !!builderProduct.needs_reattach_review,
              recalcRequired: !!builderProduct.price_recalc_required,
            })
          : Math.abs(liveTotal - frozen) > 0.005 || Math.abs(liveCustomerPrice - frozenCustomer) > 0.005
            ? "changed"
            : "current";
    const identityPatch = {
      estimate_line_id: lineId,
      module_key: line.module_key,
      source_entity: sourceEntity,
      source_project_id: line.project_id || "",
      builder_name: builderName,
      client_product_name: clientName,
      client_description: line.customer_description || "",
      product_category: line.product_category || builderProduct.product_category || "",
      production_product_type: line.production_product_type ?? builderProduct.production_product_type ?? "",
      product_notes: line.product_notes ?? builderProduct.product_notes ?? "",
      quantity: num(line.customer_quantity, 1),
      status: line.section_status === "complete" ? "complete" : "in_progress",
    };
    const pricingPatch = {
      current_recalculated_cost: liveTotal,
      price_state: nextState,
      price_delta: liveTotal - frozen,
      price_delta_percent: frozen ? ((liveTotal - frozen) / frozen) * 100 : 0,
      price_recalc_required: builderProduct.price_recalc_required || false,
      price_recalc_reason: builderProduct.price_recalc_reason || "",
    };
    const willRunPartSync = !!source && !deferPartSync && !(
      builderProduct.price_state === "legacy_frozen" && builderProduct.legacy_bom_reconciled === true
    );
    // During strict page reconciliation, Part synchronization is authoritative for
    // the final live Product economics (including manual add-ons). Avoid a
    // transient pre-Part pricing write that would be immediately overwritten by
    // the post-Part summary and churn the BuilderProduct timestamp on page open.
    const productPatch = skipUnchangedWrites && willRunPartSync
      ? identityPatch
      : { ...identityPatch, ...pricingPatch };
    if (!skipUnchangedWrites || patchDiffers(builderProduct, productPatch)) {
      const writePatch = { ...productPatch, last_price_check_at: timestamp };
      builderProduct = await replaceBuilderEntityFieldsIfUnchanged({
        entity: staffEntities.BuilderProduct,
        id: builderProduct.id,
        expectedUpdatedAt: builderProduct.updated_date || "",
        expectedFields: expectedBuilderEntityFields(builderProduct, writePatch),
        nextFields: writePatch,
        guardFields: { estimate_id: builderProduct.estimate_id },
        label: "Builder Product synchronization",
      });
    }
  }

  let partSummary = {
    partCount: num(builderProduct.part_count),
    detachedCount: num(builderProduct.detached_part_count),
    changedCount: 0,
    newPartCount: 0,
    removedPartCount: 0,
    writesPerformed: 0,
    recalcRequired: !!builderProduct.price_recalc_required,
    recalcReason: builderProduct.price_recalc_reason || "",
    usesDirectLiveReprice: false,
    currentPartsTotal: 0,
    frozenPartsTotal: 0,
    currentMarkupTotal: 0,
    frozenMarkupTotal: 0,
    manualAddonFrozenTotal: 0,
    manualAddonCurrentTotal: 0,
  };
  let effectiveLiveTotal = liveTotal;
  let effectiveLiveCustomerPrice = preserveLegacyEconomics ? liveCustomerPrice : economics.customerPrice;
  const preserveReconciledLegacyBom =
    builderProduct?.price_state === "legacy_frozen" && builderProduct?.legacy_bom_reconciled === true;
  if (source && builderProduct?.id && !preserveReconciledLegacyBom && !deferPartSync) {
    partSummary = await syncBuilderParts({
      builderProduct,
      sourceProject: source,
      acceptPrices: false,
      legacyMode: builderProduct.price_state === "legacy_frozen",
      strictCatalogs: strictPartSync,
      catalogsOverride: strictPartSync ? partSyncInputs?.catalogs || null : null,
      existingPartsOverride: strictPartSync ? partSyncInputs?.existingParts || [] : null,
      inventoryRowsOverride: strictPartSync ? partSyncInputs?.inventoryRowsOverride || new Map() : null,
      skipUnchangedWrites,
    });
    if (partSummary.usesDirectLiveReprice) {
      const manualAddonCurrent = num(partSummary.manualAddonCurrentTotal);
      const liveInternalFromParts = num(partSummary.currentPartsTotal) - num(partSummary.currentMarkupTotal);
      const liveBuilderCoreCost = liveInternalFromParts - manualAddonCurrent;
      const markupPercent = num(source?.markup_percent);
      effectiveLiveTotal = liveInternalFromParts;
      effectiveLiveCustomerPrice = liveBuilderCoreCost * (1 + markupPercent / 100) + manualAddonCurrent;
    } else {
      effectiveLiveTotal = liveTotal + num(partSummary.manualAddonCurrentTotal);
      effectiveLiveCustomerPrice = preserveLegacyEconomics
        ? liveCustomerPrice
        : economics.customerPrice + num(partSummary.manualAddonCurrentTotal);
    }
    const frozenAfterSync = num(builderProduct.frozen_cost, acceptedTotal);
    const frozenCustomerAfterSync = hasNumericValue(builderProduct.frozen_customer_price)
      ? num(builderProduct.frozen_customer_price)
      : acceptedCustomerPrice;
    const productPriceState = partSummary.detachedCount > 0
      ? "detached_parts"
      : partSummary.recalcRequired
        ? "changed"
        : builderProduct.price_state === "legacy_frozen"
          ? "legacy_frozen"
          : builderProduct.price_state === "manual"
            ? "manual"
            : partSummary.changedCount > 0 ||
                Math.abs(effectiveLiveTotal - frozenAfterSync) > 0.005 ||
                Math.abs(effectiveLiveCustomerPrice - frozenCustomerAfterSync) > 0.005
              ? "changed"
              : "current";
    const partProductPatch = {
      part_count: partSummary.partCount,
      detached_part_count: partSummary.detachedCount,
      needs_reattach_review: partSummary.detachedCount > 0,
      current_recalculated_cost: effectiveLiveTotal,
      price_state: productPriceState,
      price_delta: effectiveLiveTotal - frozenAfterSync,
      price_delta_percent: frozenAfterSync ? ((effectiveLiveTotal - frozenAfterSync) / frozenAfterSync) * 100 : 0,
      price_recalc_required: !!partSummary.recalcRequired,
      price_recalc_reason: partSummary.recalcReason || "",
    };
    if (!skipUnchangedWrites || patchDiffers(builderProduct, partProductPatch)) {
      const writePatch = skipUnchangedWrites
        ? { ...partProductPatch, last_price_check_at: timestamp }
        : partProductPatch;
      builderProduct = await replaceBuilderEntityFieldsIfUnchanged({
        entity: staffEntities.BuilderProduct,
        id: builderProduct.id,
        expectedUpdatedAt: builderProduct.updated_date || "",
        expectedFields: expectedBuilderEntityFields(builderProduct, writePatch),
        nextFields: writePatch,
        guardFields: { estimate_id: builderProduct.estimate_id },
        label: "Builder Product synchronization",
      });
    }
  }

  const frozenCost = isNew ? num(builderProduct.frozen_cost) : acceptedTotal;
  const frozenCustomerPrice = hasNumericValue(builderProduct.frozen_customer_price)
    ? num(builderProduct.frozen_customer_price)
    : acceptedCustomerPrice;
  const linePatch = {
    line_id: lineId,
    builder_product_id: builderProduct.id,
    builder_name: builderName,
    client_product_name: clientName,
    product_category: line.product_category || builderProduct.product_category || "",
    production_product_type: line.production_product_type ?? builderProduct.production_product_type ?? "",
    product_notes: line.product_notes ?? builderProduct.product_notes ?? "",
    total_snapshot: frozenCost,
    live_total_snapshot: effectiveLiveTotal,
    customer_price_snapshot: frozenCustomerPrice,
    live_customer_price_snapshot: effectiveLiveCustomerPrice,
    price_state: builderProduct.price_state || (isNew ? "unchecked" : "legacy_frozen"),
    price_recalc_required: !!builderProduct.price_recalc_required,
    price_recalc_reason: builderProduct.price_recalc_reason || "",
    detached_part_count: num(builderProduct.detached_part_count),
    needs_reattach_review: !!builderProduct.needs_reattach_review,
  };
  const lineChanged = patchDiffers(line, linePatch);
  const nextLine = skipUnchangedWrites && !lineChanged
    ? line
    : {
        ...line,
        ...linePatch,
        last_price_check_at: timestamp,
        updated_date_snapshot: source?.updated_date || line.updated_date_snapshot,
      };

  return {
    line: nextLine,
    builderProduct,
    changed: skipUnchangedWrites ? lineChanged : stableStringify(nextLine) !== stableStringify(line),
    partSyncInputs,
  };
}

export async function ensureEstimateBuilderProducts(estimate, { strictReconciliation = false, onWarning = null } = {}) {
  if (!estimate?.id) return estimate;
  const original = estimate.line_items || [];
  const lineItems = [];
  let changed = false;

  for (const line of original) {
    try {
      if (line?.price_acceptance_pending?.kind === "builder_product_remove") {
        // Product removal may already have deleted its owned source and/or Builder.
        // Preserve the exact durable line without reconciliation warnings or writes
        // until the specialized Remove recovery action finishes the operation.
        lineItems.push(line);
        continue;
      }
      let sourceProjectOverride;
      if (strictReconciliation) {
        const mod = getModule(line?.module_key);
        if (mod && line?.project_id) {
          try {
            sourceProjectOverride = await staffEntities[mod.entity].get(line.project_id);
          } catch (error) {
            throw new Error(`${getModuleLabel(line.module_key) || "Builder"} source could not be verified: ${error?.message || "read failed"}`);
          }
          if (!sourceProjectOverride) {
            throw new Error(`${getModuleLabel(line.module_key) || "Builder"} source could not be verified. The saved Product snapshot was retained.`);
          }
        }
      }
      const result = await ensureBuilderProductForLine({
        estimate,
        line,
        isNew: false,
        strictPartSync: strictReconciliation,
        skipUnchangedWrites: strictReconciliation,
        sourceProjectOverride,
      });
      lineItems.push(result.line);
      changed = changed || result.changed;
    } catch (error) {
      if (!strictReconciliation) throw error;
      const warning = {
        line_id: line.line_id || "",
        builder_product_id: line.builder_product_id || "",
        product_name: line.client_product_name || line.project_name || getModuleLabel(line.module_key) || "Product",
        message: error?.message || "This Product could not be verified against its Builder catalogs. The saved Product snapshot was retained.",
      };
      onWarning?.(warning);
      lineItems.push(line);
    }
  }

  if (changed) {
    const savedEstimate = await replaceEstimateFieldsIfUnchanged({
      entity: staffEntities.AllInOneEstimate,
      estimateId: estimate.id,
      expectedFields: expectedEstimateFields(estimate, { line_items: lineItems }),
      nextFields: { line_items: lineItems },
      label: "Builder estimate line synchronization",
    });
    return { ...estimate, ...savedEstimate, line_items: savedEstimate.line_items || lineItems };
  }
  return { ...estimate, line_items: lineItems };
}

export async function recordBuilderSave({ estimateId, line, sourceProject, liveTotal, internalCost, customerPrice, expectedPendingKey }) {
  if (!estimateId || !line) return line;
  if (!sourceProject || typeof sourceProject !== "object") {
    throw new Error("The saved Builder source could not be verified. Product pricing and Parts were not synchronized.");
  }
  const estimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!estimate) throw new Error("Estimate could not be verified before synchronizing this Builder save.");
  // Source-only hints omit the Builder ID; two absent IDs are not an identity.
  const currentLine = (estimate.line_items || []).find(
    (item) => item.module_key === line.module_key && (
      (line.builder_product_id && item.builder_product_id === line.builder_product_id)
      || (line.project_id && item.project_id === line.project_id)
    )
  ) || line;

  const existingPending = pendingBuilderMutation(currentLine);
  if (expectedPendingKey !== undefined && existingPending?.key !== expectedPendingKey) {
    throw new Error("The pending Builder operation changed before recovery. Reload the estimate before continuing.");
  }
  if (existingPending) {
    if (existingPending.kind === "builder_product_remove") {
      throw new Error("This Product is being removed. Use Resume Product Remove before opening or saving its Builder again.");
    }
    const pendingBuilderId = currentLine.builder_product_id || existingPending.builder_product_id || "";
    const [pendingBuilder, pendingParts] = await Promise.all([
      pendingBuilderId ? staffEntities.BuilderProduct.get(pendingBuilderId) : Promise.resolve(null),
      pendingBuilderId ? loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: pendingBuilderId }, sort: "sort_order", label: "Builder Parts" }) : Promise.resolve([]),
    ]);
    if (!pendingBuilder?.id || !Array.isArray(pendingParts)) {
      throw new Error("The pending initial price acceptance could not verify its Builder Product or Parts. The recovery marker was retained.");
    }
    const recovered = await resumeBuilderMutation({
      estimateId,
      estimate,
      builder: pendingBuilder,
      parts: pendingParts,
      line: currentLine,
      pending: existingPending,
      applyPartPlan: applyBuilderPartPriceAcceptancePlan,
    });
    return recovered?.line || currentLine;
  }

  await assertEstimateProductMutationAllowed(estimate);

  const ensured = await ensureBuilderProductForLine({
    estimate,
    line: currentLine,
    isNew: !currentLine.builder_product_id,
    deferPartSync: true,
    sourceProjectOverride: sourceProject ?? undefined,
  });
  const builder = ensured.builderProduct;
  const matchesCurrentLine = (item) => item.module_key === currentLine.module_key && (
    (builder?.id && item.builder_product_id === builder.id)
    || (currentLine.project_id && item.project_id === currentLine.project_id)
  );
  if (builder && !ensured.partSyncInputs) {
    throw new Error("Builder catalogs could not be preverified. Product pricing and Parts were not synchronized.");
  }
  const timestamp = nowIso();
  const sourceTotal = num(liveTotal, sourceProjectTotal(currentLine, sourceProject));
  const economics = sourceProjectEconomics(currentLine.module_key, sourceProject, sourceTotal);
  const nextLiveTotal = hasNumericValue(internalCost) ? num(internalCost) : economics.internalCost;
  const nextLiveCustomerPrice = hasNumericValue(customerPrice) ? num(customerPrice) : economics.customerPrice;
  const previousFrozenTotal = num(builder?.frozen_cost, num(currentLine.total_snapshot));
  const previousFrozenCustomerPrice = hasNumericValue(builder?.frozen_customer_price)
    ? num(builder.frozen_customer_price)
    : acceptedCustomerUnitPrice(currentLine);
  const wantsInitialFreeze = builder?.price_state === "unchecked" && previousFrozenTotal === 0;

  let partSummary = {
    partCount: num(builder?.part_count),
    detachedCount: num(builder?.detached_part_count),
    changedCount: 0,
    newPartCount: 0,
    removedPartCount: 0,
    recalcRequired: false,
    recalcReason: "",
    usesDirectLiveReprice: false,
    currentPartsTotal: 0,
    frozenPartsTotal: 0,
    currentMarkupTotal: 0,
    frozenMarkupTotal: 0,
    manualAddonFrozenTotal: 0,
    manualAddonCurrentTotal: 0,
  };

  if (builder) {
    // Always detect first without accepting prices. A missing inventory link must
    // block the initial freeze just like it blocks later Update Price actions.
    partSummary = await syncBuilderParts({
      builderProduct: builder,
      sourceProject: sourceProject || {},
      acceptPrices: false,
      legacyMode: builder.price_state === "legacy_frozen",
      // This path runs only after the authoritative Builder calculator has
      // produced and saved sourceProject/liveTotal. Mark the current inventory
      // pricing used by that calculation so Update Price can safely accept it.
      builderRecalculated: true,
      strictCatalogs: true,
      catalogsOverride: ensured.partSyncInputs.catalogs,
      existingPartsOverride: ensured.partSyncInputs.existingParts,
      inventoryRowsOverride: ensured.partSyncInputs.inventoryRowsOverride,
    });
  }

  const effectiveLiveTotal = nextLiveTotal + num(partSummary.manualAddonCurrentTotal);
  const effectiveLiveCustomerPrice = nextLiveCustomerPrice + num(partSummary.manualAddonCurrentTotal);
  const canInitialFreeze = wantsInitialFreeze && partSummary.detachedCount === 0;
  const acceptedTotal = canInitialFreeze ? effectiveLiveTotal : previousFrozenTotal;
  const calculatedState = canInitialFreeze
    ? "current"
    : partSummary.changedCount > 0 ||
        Math.abs(effectiveLiveTotal - acceptedTotal) > 0.005 ||
        Math.abs(effectiveLiveCustomerPrice - previousFrozenCustomerPrice) > 0.005
      ? "changed"
      : "current";
  const productState = partSummary.detachedCount > 0
    ? "detached_parts"
    : builder?.price_state === "legacy_frozen"
      ? "legacy_frozen"
      : calculatedState;

  if (builder && canInitialFreeze) {
    // Build the complete frozen Part plan without applying it. The Estimate line
    // recovery marker below must become durable before the first accepted-price
    // write so an interrupted initial freeze can always resume deterministically.
    const partAcceptance = await acceptBuilderPartPrices(builder.id, {
      builderOverride: builder,
      partsOverride: partSummary.parts || [],
      apply: false,
      timestamp,
    });
    if (partAcceptance.detachedCount > 0) {
      // Defensive guard: keep the Product unfrozen until every Part is resolved.
      partSummary.detachedCount = partAcceptance.detachedCount;
    } else {
      const initialAcceptedTotal = effectiveLiveTotal;
      const initialAcceptedCustomerPrice = effectiveLiveCustomerPrice;
      const operationKey = `builder_initial_freeze:${builder.id}:${num(builder.builder_version, 1)}:${snapshotHash({
        estimate_updated_date: estimate.updated_date || "",
        estimate_line_id: currentLine.line_id || ensured.line.line_id || "",
        source_updated_date: sourceProject?.updated_date || "",
        source_hash: snapshotHash(sourceProject || {}),
        total: initialAcceptedTotal,
        customer_price: initialAcceptedCustomerPrice,
        part_updates: partAcceptance.acceptancePlan?.part_updates || [],
      })}`;
      const builderPatch = {
        builder_snapshot: sourceProject || {},
        builder_snapshot_at: timestamp,
        builder_snapshot_source_updated_date: sourceProject?.updated_date || timestamp,
        builder_snapshot_hash: snapshotHash(sourceProject || {}),
        frozen_cost: initialAcceptedTotal,
        frozen_customer_price: initialAcceptedCustomerPrice,
        current_recalculated_cost: effectiveLiveTotal,
        price_state: "current",
        price_delta: 0,
        price_delta_percent: 0,
        price_recalc_required: false,
        price_recalc_reason: "",
        last_price_check_at: timestamp,
        last_price_update_at: timestamp,
        builder_version: num(builder.builder_version, 1) + 1,
        part_count: partSummary.partCount,
        detached_part_count: 0,
        needs_reattach_review: false,
      };
      const linePatch = {
        line_id: currentLine.line_id || ensured.line.line_id,
        builder_product_id: builder.id,
        builder_name: currentLine.builder_name || ensured.line.builder_name,
        client_product_name: currentLine.client_product_name || ensured.line.client_product_name,
        total_snapshot: initialAcceptedTotal,
        live_total_snapshot: effectiveLiveTotal,
        customer_price_snapshot: initialAcceptedCustomerPrice,
        live_customer_price_snapshot: effectiveLiveCustomerPrice,
        price_state: "current",
        price_recalc_required: false,
        price_recalc_reason: "",
        detached_part_count: 0,
        needs_reattach_review: false,
        last_price_check_at: timestamp,
        last_price_update_at: timestamp,
        updated_date_snapshot: sourceProject?.updated_date || timestamp,
      };
      const revision = {
        builder_product_id: builder.id,
        estimate_id: estimateId,
        reason: "initial_freeze",
        previous_total_cost: 0,
        new_total_cost: initialAcceptedTotal,
        previous_customer_price: 0,
        new_customer_price: initialAcceptedCustomerPrice,
        changed_parts: partAcceptance.changedParts || [],
        builder_snapshot_before: builder.builder_snapshot || {},
        builder_snapshot_after: sourceProject || {},
        price_snapshot_before: { total: 0, customer_price: 0 },
        price_snapshot_after: { total: initialAcceptedTotal, customer_price: initialAcceptedCustomerPrice },
        notes: "Initial accepted/frozen product price.",
      };
      const pending = {
        key: operationKey,
        kind: "builder_initial_freeze",
        started_at: timestamp,
        estimate_id: estimateId,
        estimate_line_id: linePatch.line_id || builder.estimate_line_id || "",
        builder_product_id: builder.id,
        builder_updated_date_before: builder.updated_date || "",
        builder_version_before: num(builder.builder_version, 1),
        part_acceptance_plan: partAcceptance.acceptancePlan || {},
        builder_patch: builderPatch,
        line_patch: linePatch,
        revision,
      };

      const preMarkerEstimate = await staffEntities.AllInOneEstimate.get(estimateId);
      if (!preMarkerEstimate) throw new Error("Estimate could not be verified before starting the initial price freeze.");
      if (
        estimate.updated_date &&
        preMarkerEstimate.updated_date &&
        estimate.updated_date !== preMarkerEstimate.updated_date
      ) {
        throw new Error("This estimate changed in another session while the Builder was being saved. Initial pricing was not frozen; reload the Estimate before retrying.");
      }
      const preMarkerLine = (preMarkerEstimate.line_items || []).find(matchesCurrentLine);
      if (!preMarkerLine) {
        throw new Error("This Product is no longer part of the estimate. Initial pricing was not frozen.");
      }
      const markedLines = (preMarkerEstimate.line_items || []).map((item) =>
        item === preMarkerLine
          ? {
              ...item,
              line_id: linePatch.line_id,
              builder_product_id: builder.id,
              builder_name: linePatch.builder_name,
              client_product_name: linePatch.client_product_name,
              price_acceptance_pending: pending,
            }
          : item
      );
      await replaceEstimateFieldsIfUnchanged({
        entity: staffEntities.AllInOneEstimate,
        estimateId,
        expectedFields: expectedEstimateFields(preMarkerEstimate, { line_items: markedLines }),
        nextFields: { line_items: markedLines },
        label: "Builder initial price-freeze recovery marker",
      });

      const [markedEstimate, currentBuilder, currentParts] = await Promise.all([
        staffEntities.AllInOneEstimate.get(estimateId),
        staffEntities.BuilderProduct.get(builder.id),
        loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" }),
      ]);
      const markedLine = (markedEstimate?.line_items || []).find(matchesCurrentLine);
      const canonicalPending = pendingBuilderMutation(markedLine);
      if (!canonicalPending || canonicalPending.key !== operationKey) {
        throw new Error("Another Builder price-acceptance operation won the recovery marker race. Reload before continuing.");
      }
      const recovered = await resumeBuilderMutation({
        estimateId,
        estimate: markedEstimate,
        builder: currentBuilder,
        parts: currentParts,
        line: markedLine,
        pending: canonicalPending,
        applyPartPlan: applyBuilderPartPriceAcceptancePlan,
      });
      return recovered?.line || markedLine || currentLine;
    }
  }

  // A successful initial freeze returns through the recovery path above. Reaching
  // this point means this was a normal recalculation/save or the first freeze was
  // blocked by detached Parts, so no accepted-price revision is completed here.
  const initialFreezeCompleted = false;
  const finalAcceptedTotal = initialFreezeCompleted ? effectiveLiveTotal : previousFrozenTotal;
  const finalAcceptedCustomerPrice = initialFreezeCompleted ? effectiveLiveCustomerPrice : previousFrozenCustomerPrice;
  const finalProductState = partSummary.detachedCount > 0
    ? "detached_parts"
    : initialFreezeCompleted
      ? "current"
      : productState;

  if (builder) {
    const nextRevision = num(builder.builder_version, 1) + (initialFreezeCompleted ? 1 : 0);
    const builderSavePatch = {
      builder_snapshot: sourceProject || {},
      builder_snapshot_at: timestamp,
      builder_snapshot_source_updated_date: sourceProject?.updated_date || timestamp,
      builder_snapshot_hash: snapshotHash(sourceProject || {}),
      frozen_cost: finalAcceptedTotal,
      frozen_customer_price: finalAcceptedCustomerPrice,
      current_recalculated_cost: effectiveLiveTotal,
      price_state: finalProductState,
      price_delta: effectiveLiveTotal - finalAcceptedTotal,
      price_delta_percent: finalAcceptedTotal ? ((effectiveLiveTotal - finalAcceptedTotal) / finalAcceptedTotal) * 100 : 0,
      // The authoritative Builder calculator just ran, so any earlier stale-catalog
      // block is now resolved even if the user has not accepted the new price yet.
      price_recalc_required: false,
      price_recalc_reason: "",
      last_price_check_at: timestamp,
      last_price_update_at: initialFreezeCompleted ? timestamp : builder.last_price_update_at,
      builder_version: nextRevision,
      part_count: partSummary.partCount,
      detached_part_count: partSummary.detachedCount,
      needs_reattach_review: partSummary.detachedCount > 0,
    };
    await replaceBuilderEntityFieldsIfUnchanged({
      entity: staffEntities.BuilderProduct,
      id: builder.id,
      expectedUpdatedAt: builder.updated_date || "",
      expectedFields: expectedBuilderEntityFields(builder, builderSavePatch),
      nextFields: builderSavePatch,
      guardFields: { estimate_id: estimateId },
      label: "Builder Product save",
    });

  }

  const nextLines = (estimate.line_items || []).map((item) => {
    if (!matchesCurrentLine(item)) return item;
    return {
      ...item,
      line_id: item.line_id || ensured.line.line_id,
      builder_product_id: builder?.id || item.builder_product_id,
      builder_name: item.builder_name || ensured.line.builder_name,
      client_product_name: item.client_product_name || ensured.line.client_product_name,
      total_snapshot: finalAcceptedTotal,
      live_total_snapshot: effectiveLiveTotal,
      customer_price_snapshot: finalAcceptedCustomerPrice,
      live_customer_price_snapshot: effectiveLiveCustomerPrice,
      price_state: finalProductState,
      price_recalc_required: false,
      price_recalc_reason: "",
      detached_part_count: partSummary.detachedCount,
      needs_reattach_review: partSummary.detachedCount > 0,
      last_price_check_at: timestamp,
      last_price_update_at: initialFreezeCompleted ? timestamp : item.last_price_update_at,
      updated_date_snapshot: sourceProject?.updated_date || timestamp,
    };
  });
  const savedEstimate = await replaceEstimateFieldsIfUnchanged({
    entity: staffEntities.AllInOneEstimate,
    estimateId,
    expectedFields: expectedEstimateFields(estimate, { line_items: nextLines }),
    nextFields: { line_items: nextLines },
    label: "Builder save Estimate line synchronization",
  });
  const savedLines = savedEstimate.line_items || nextLines;
  return savedLines.find(matchesCurrentLine) || currentLine;
}

export async function deleteBuilderProductCascade(builderProductId) {
  if (!builderProductId) return { deleted: false, reason: "missing_builder_product_id" };
  const builder = await staffEntities.BuilderProduct.get(builderProductId);
  if (!builder?.id) return { deleted: true, alreadyDeleted: true };

  const [parts, groups, revisions] = await Promise.all([
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Parts" }),
    loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Part Groups" }),
    loadAllEntityRows({ entity: base44.entities.BuilderPriceRevision, query: { builder_product_id: builderProductId }, sort: "revision_number", label: "Builder price revisions" }),
  ]);
  if (!Array.isArray(parts) || !Array.isArray(groups) || !Array.isArray(revisions)) {
    throw new Error("Builder Product cascade could not verify all owned records before deletion.");
  }

  let partDeletes = 0;
  let groupDeletes = 0;
  let revisionDeletes = 0;
  for (const row of parts) {
    await deleteBuilderEntityIfUnchanged({
      entity: staffEntities.BuilderPart,
      record: row,
      guardFields: { builder_product_id: builderProductId },
      label: `Builder Part “${row.part_name || "Part"}” cascade delete`,
    });
    partDeletes += 1;
  }
  for (const row of groups) {
    await deleteBuilderEntityIfUnchanged({
      entity: staffEntities.BuilderPartGroup,
      record: row,
      guardFields: { builder_product_id: builderProductId },
      label: `Builder Part Group “${row.group_name || "Part Group"}” cascade delete`,
    });
    groupDeletes += 1;
  }
  for (const row of revisions) {
    await deleteBuilderEntityIfUnchanged({
      entity: base44.entities.BuilderPriceRevision,
      record: row,
      guardFields: { builder_product_id: builderProductId },
      label: "Builder price revision cascade delete",
    });
    revisionDeletes += 1;
  }
  await deleteBuilderEntityIfUnchanged({
    entity: staffEntities.BuilderProduct,
    record: builder,
    label: "Builder Product cascade delete",
  });
  return { deleted: true, partDeletes, groupDeletes, revisionDeletes };
}


export async function acceptBuilderPrice({ estimateId, line, note = "Price updated from current builder calculation.", expectedEstimateUpdatedAt = "" }) {
  if (!estimateId || !line?.builder_product_id) return null;
  const [estimate, builder, parts] = await Promise.all([
    staffEntities.AllInOneEstimate.get(estimateId),
    staffEntities.BuilderProduct.get(line.builder_product_id),
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: line.builder_product_id }, sort: "sort_order", label: "Builder Parts" }),
  ]);
  if (!estimate || !builder) throw new Error("Estimate pricing could not be verified. Reload before updating this Product price.");
  if (!Array.isArray(parts)) throw new Error("Builder Parts could not be verified. No price was accepted.");
  if (builder.estimate_id && builder.estimate_id !== estimateId) {
    throw new Error("This Builder Product no longer belongs to the current estimate. Reload before updating its price.");
  }
  const verifiedEstimateLine = (estimate.line_items || []).find((item) => item.builder_product_id === builder.id);
  if (!verifiedEstimateLine) throw new Error("This Product is no longer part of the estimate. Reload before updating its price.");
  if (builder.estimate_line_id && verifiedEstimateLine.line_id && builder.estimate_line_id !== verifiedEstimateLine.line_id) {
    throw new Error("This Product line changed since its Builder was linked. Reload before updating its price.");
  }
  if (parts.some((part) => part?.builder_product_id !== builder.id)) {
    throw new Error("One or more Builder Parts no longer belong to this Product. Reload before updating its price.");
  }

  const existingPending = pendingBuilderMutation(verifiedEstimateLine);
  if (existingPending) {
    return resumeBuilderMutation({
      estimateId,
      estimate,
      builder,
      parts,
      line: verifiedEstimateLine,
      pending: existingPending,
      applyPartPlan: applyBuilderPartPriceAcceptancePlan,
    });
  }

  // If the final Estimate write succeeded but its response was lost, the browser
  // may retry with the pre-operation timestamp. Verify the complete accepted
  // server state before enforcing that stale timestamp so the retry becomes a
  // no-op instead of creating a second pricing operation.
  const serverAlreadyCurrent =
    builder.price_state === "current" &&
    verifiedEstimateLine.price_state === "current" &&
    sameNumber(builder.frozen_cost, builder.current_recalculated_cost) &&
    sameNumber(verifiedEstimateLine.total_snapshot, verifiedEstimateLine.live_total_snapshot) &&
    sameNumber(acceptedCustomerUnitPrice(verifiedEstimateLine), liveCustomerUnitPrice(verifiedEstimateLine));
  if (serverAlreadyCurrent) {
    return { blocked: false, alreadyCompleted: true, changedParts: [], line: verifiedEstimateLine };
  }

  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: expectedEstimateUpdatedAt });
  const timestamp = nowIso();
  const partAcceptance = await acceptBuilderPartPrices(builder.id, {
    builderOverride: builder,
    partsOverride: parts,
    apply: false,
    timestamp,
  });
  if (partAcceptance.detachedCount > 0) {
    const blockedTimestamp = nowIso();
    const detachedBuilderPatch = {
      price_state: "detached_parts",
      detached_part_count: partAcceptance.detachedCount,
      needs_reattach_review: true,
      last_price_check_at: blockedTimestamp,
    };
    await replaceBuilderEntityFieldsIfUnchanged({
      entity: staffEntities.BuilderProduct,
      id: builder.id,
      expectedUpdatedAt: builder.updated_date || "",
      expectedFields: expectedBuilderEntityFields(builder, detachedBuilderPatch),
      nextFields: detachedBuilderPatch,
      guardFields: { estimate_id: estimateId },
      label: "Builder detached-parts status",
    });
    const blockedLines = (estimate.line_items || []).map((item) =>
      item.builder_product_id === builder.id
        ? {
            ...item,
            price_state: "detached_parts",
            detached_part_count: partAcceptance.detachedCount,
            needs_reattach_review: true,
            last_price_check_at: blockedTimestamp,
          }
        : item
    );
    const savedEstimate = await replaceEstimateFieldsIfUnchanged({
      entity: staffEntities.AllInOneEstimate,
      estimateId,
      expectedFields: expectedEstimateFields(estimate, { line_items: blockedLines }),
      nextFields: { line_items: blockedLines },
      label: "Builder detached-parts Estimate state",
    });
    const savedLines = savedEstimate.line_items || blockedLines;
    return {
      blocked: true,
      reason: "detached_parts",
      detachedCount: partAcceptance.detachedCount,
      detachedParts: partAcceptance.detachedParts || [],
      line: savedLines.find((item) => item.builder_product_id === builder.id) || line,
    };
  }

  if (partAcceptance.recalcRequired) {
    const blockedTimestamp = nowIso();
    const reason = partAcceptance.recalcReason || "Master Inventory changed after this Builder was last calculated. Reopen and save the Builder before accepting Update Price.";
    const recalcBuilderPatch = {
      price_state: "changed",
      price_recalc_required: true,
      price_recalc_reason: reason,
      last_price_check_at: blockedTimestamp,
    };
    await replaceBuilderEntityFieldsIfUnchanged({
      entity: staffEntities.BuilderProduct,
      id: builder.id,
      expectedUpdatedAt: builder.updated_date || "",
      expectedFields: expectedBuilderEntityFields(builder, recalcBuilderPatch),
      nextFields: recalcBuilderPatch,
      guardFields: { estimate_id: estimateId },
      label: "Builder recalc-required status",
    });
    const blockedLines = (estimate.line_items || []).map((item) =>
      item.builder_product_id === builder.id
        ? {
            ...item,
            price_state: "changed",
            price_recalc_required: true,
            price_recalc_reason: reason,
            last_price_check_at: blockedTimestamp,
          }
        : item
    );
    const savedEstimate = await replaceEstimateFieldsIfUnchanged({
      entity: staffEntities.AllInOneEstimate,
      estimateId,
      expectedFields: expectedEstimateFields(estimate, { line_items: blockedLines }),
      nextFields: { line_items: blockedLines },
      label: "Builder recalc-required Estimate state",
    });
    const savedLines = savedEstimate.line_items || blockedLines;
    return {
      blocked: true,
      reason: "recalc_required",
      recalcReason: reason,
      recalcParts: partAcceptance.recalcParts || [],
      line: savedLines.find((item) => item.builder_product_id === builder.id) || line,
    };
  }

  const currentEstimateLine = verifiedEstimateLine;
  const previousTotal = num(builder.frozen_cost, num(currentEstimateLine.total_snapshot));
  const nextTotal = num(builder.current_recalculated_cost, num(currentEstimateLine.live_total_snapshot, previousTotal));
  const previousCustomerPrice = hasNumericValue(builder.frozen_customer_price)
    ? num(builder.frozen_customer_price)
    : acceptedCustomerUnitPrice(currentEstimateLine);
  const nextCustomerPrice = liveCustomerUnitPrice(currentEstimateLine);
  const noServerChange =
    sameNumber(previousTotal, nextTotal) &&
    sameNumber(previousCustomerPrice, nextCustomerPrice) &&
    (partAcceptance.changedParts || []).length === 0 &&
    builder.price_state === "current" &&
    currentEstimateLine.price_state === "current";
  if (noServerChange) {
    return { blocked: false, alreadyCompleted: true, changedParts: [], line: currentEstimateLine };
  }

  const operationKey = `builder_update_price:${builder.id}:${num(builder.builder_version, 1)}:${snapshotHash({
    estimate_updated_date: estimate.updated_date || "",
    estimate_line_id: currentEstimateLine.line_id || "",
    previous_total: previousTotal,
    next_total: nextTotal,
    previous_customer_price: previousCustomerPrice,
    next_customer_price: nextCustomerPrice,
    part_updates: partAcceptance.acceptancePlan?.part_updates || [],
  })}`;
  const builderPatch = {
    frozen_cost: nextTotal,
    frozen_customer_price: nextCustomerPrice,
    price_state: "current",
    price_delta: 0,
    price_delta_percent: 0,
    price_recalc_required: false,
    price_recalc_reason: "",
    detached_part_count: 0,
    needs_reattach_review: false,
    part_count: partAcceptance.activePartCount ?? builder.part_count,
    last_price_update_at: timestamp,
    last_price_update_note: note,
    last_price_check_at: timestamp,
    builder_version: num(builder.builder_version, 1) + 1,
  };
  const linePatch = {
    total_snapshot: nextTotal,
    live_total_snapshot: nextTotal,
    customer_price_snapshot: nextCustomerPrice,
    live_customer_price_snapshot: nextCustomerPrice,
    price_state: "current",
    price_recalc_required: false,
    price_recalc_reason: "",
    detached_part_count: 0,
    needs_reattach_review: false,
    last_price_update_at: timestamp,
    last_price_check_at: timestamp,
  };
  const revision = {
    builder_product_id: builder.id,
    estimate_id: estimateId,
    reason: "update_price",
    previous_total_cost: previousTotal,
    new_total_cost: nextTotal,
    previous_customer_price: previousCustomerPrice,
    new_customer_price: nextCustomerPrice,
    changed_parts: partAcceptance.changedParts || [],
    builder_snapshot_before: builder.builder_snapshot || {},
    builder_snapshot_after: builder.builder_snapshot || {},
    price_snapshot_before: { total: previousTotal, customer_price: previousCustomerPrice },
    price_snapshot_after: { total: nextTotal, customer_price: nextCustomerPrice },
    notes: note,
  };
  const pending = {
    key: operationKey,
    kind: "builder_update_price",
    started_at: timestamp,
    estimate_id: estimateId,
    estimate_line_id: currentEstimateLine.line_id || builder.estimate_line_id || "",
    builder_product_id: builder.id,
    builder_updated_date_before: builder.updated_date || "",
    builder_version_before: num(builder.builder_version, 1),
    part_acceptance_plan: partAcceptance.acceptancePlan || {},
    builder_patch: builderPatch,
    line_patch: linePatch,
    revision,
  };

  // The Estimate line marker is the first write. It survives any later network or
  // multi-record failure and is removed only by the final accepted line write.
  const markedLines = (estimate.line_items || []).map((item) =>
    item.builder_product_id === builder.id
      ? { ...item, price_acceptance_pending: pending }
      : item
  );
  await replaceEstimateFieldsIfUnchanged({
    entity: staffEntities.AllInOneEstimate,
    estimateId,
    expectedFields: expectedEstimateFields(estimate, { line_items: markedLines }),
    nextFields: { line_items: markedLines },
    label: "Builder price-acceptance recovery marker",
  });

  // Re-read all mutable inputs after the marker is durable. If a concurrent edit
  // won the race, the stored expected versions make recovery fail closed rather
  // than mixing two Product states.
  const [markedEstimate, currentBuilder, currentParts] = await Promise.all([
    staffEntities.AllInOneEstimate.get(estimateId),
    staffEntities.BuilderProduct.get(builder.id),
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" }),
  ]);
  const markedLine = (markedEstimate?.line_items || []).find((item) => item.builder_product_id === builder.id);
  const canonicalPending = pendingBuilderMutation(markedLine);
  if (!canonicalPending || canonicalPending.key !== operationKey) {
    throw new Error("Another Update Price operation won the recovery marker race. Reload before continuing.");
  }

  return resumeBuilderMutation({
    estimateId,
    estimate: markedEstimate,
    builder: currentBuilder,
    parts: currentParts,
    line: markedLine,
    pending: canonicalPending,
    applyPartPlan: applyBuilderPartPriceAcceptancePlan,
  });
}

import { base44 } from "@/api/base44Client";
import { assertEstimateProductMutationAllowed } from "@/components/estimator/estimateMutationGuard";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { expectedEstimateFields, replaceEstimateFieldsIfUnchanged } from "@/components/estimator/estimatePersistence";
import { deleteBuilderEntityIfUnchanged, expectedBuilderEntityFields, expectedEntityFields, replaceBuilderEntityFieldsIfUnchanged, replaceEntityFieldsIfUnchanged } from "./builderEntityPersistence";
import { createBuilderPartGroupWithRecovery } from "./builderPartGroupPersistence";
import { staffEntities } from "@/components/staff/staffEntities";

const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;

function stableValue(value) {
  if (Array.isArray(value)) return value.map(stableValue);
  if (!value || typeof value !== "object") return value;
  return Object.fromEntries(
    Object.keys(value)
      .sort()
      .filter((key) => !["created_by", "created_by_id"].includes(key))
      .map((key) => [key, stableValue(value[key])])
  );
}

function sameSubstantiveValue(a, b) {
  const bothPresent = a !== null && a !== undefined && a !== "" && b !== null && b !== undefined && b !== "";
  if (bothPresent && Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
    return Math.abs(num(a) - num(b)) <= 0.005;
  }
  return JSON.stringify(stableValue(a ?? null)) === JSON.stringify(stableValue(b ?? null));
}

export function recoveryPatchDiffers(record, patch) {
  return Object.entries(patch || {}).some(([key, value]) => !sameSubstantiveValue(record?.[key], value));
}

export function builderMutationHash(value) {
  const text = JSON.stringify(stableValue(value ?? null));
  let hash = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return `fnv1a-${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

export function pendingBuilderMutation(line) {
  const pending = line?.price_acceptance_pending;
  return pending && typeof pending === "object" && String(pending.key || "").trim() ? pending : null;
}

// Recovery markers are durable: the only safe way to clear one is to resume it
// and verify its writes completed. Stale markers are therefore surfaced, never
// silently deleted — a >24h marker means a mutation needs explicit resume review.
export const STALE_PENDING_BUILDER_MUTATION_MS = 24 * 60 * 60 * 1000;

export function pendingBuilderMutationAge(line, now = Date.now()) {
  const pending = pendingBuilderMutation(line);
  const started = Date.parse(pending?.started_at || "");
  return Number.isFinite(started) ? Math.max(0, Number(now) - started) : null;
}

export function pendingBuilderMutationIsStale(line, olderThanMs = STALE_PENDING_BUILDER_MUTATION_MS, now = Date.now()) {
  const age = pendingBuilderMutationAge(line, now);
  return age !== null && age >= Math.max(0, Number(olderThanMs) || 0);
}

export async function markBuilderMutationPending({ estimate, builder, pending }) {
  if (!estimate?.id || !builder?.id || !pending?.key) {
    throw new Error("Builder mutation recovery could not be initialized.");
  }
  const latestEstimate = await staffEntities.AllInOneEstimate.get(estimate.id);
  if (!latestEstimate) throw new Error("Estimate could not be verified before starting this Builder mutation.");
  if (
    estimate.updated_date &&
    latestEstimate.updated_date &&
    estimate.updated_date !== latestEstimate.updated_date
  ) {
    throw new Error("This estimate changed in another session before the Builder mutation could start. No Product or Part pricing was changed.");
  }
  const latestLine = (latestEstimate.line_items || []).find((item) => item.builder_product_id === builder.id);
  if (!latestLine) throw new Error("This Product is no longer part of the estimate. No Product or Part pricing was changed.");
  const lineItems = (latestEstimate.line_items || []).map((item) =>
    item.builder_product_id === builder.id
      ? { ...item, price_acceptance_pending: pending }
      : item
  );
  await replaceEstimateFieldsIfUnchanged({
    entity: staffEntities.AllInOneEstimate,
    estimateId: estimate.id,
    expectedFields: expectedEstimateFields(latestEstimate, { line_items: lineItems }),
    nextFields: { line_items: lineItems },
    label: "Builder mutation recovery marker",
  });

  const [markedEstimate, currentBuilder, currentParts] = await Promise.all([
    staffEntities.AllInOneEstimate.get(estimate.id),
    staffEntities.BuilderProduct.get(builder.id),
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder recovery Parts" }),
  ]);
  const markedLine = (markedEstimate?.line_items || []).find((item) => item.builder_product_id === builder.id);
  const canonicalPending = pendingBuilderMutation(markedLine);
  if (!canonicalPending || canonicalPending.key !== pending.key) {
    throw new Error("Another Builder mutation won the recovery marker race. Reload before continuing.");
  }
  return { markedEstimate, currentBuilder, currentParts, markedLine, canonicalPending };
}

function validatePendingBuilderMutation(pending, { estimateId, builder, line }) {
  if (!pending || !String(pending.kind || "").startsWith("builder_")) {
    throw new Error("The pending Builder recovery marker is invalid. No pricing or Part change was continued.");
  }
  if (
    String(pending.estimate_id || "") !== String(estimateId || "") ||
    String(pending.builder_product_id || "") !== String(builder?.id || "") ||
    (pending.estimate_line_id && line?.line_id && pending.estimate_line_id !== line.line_id)
  ) {
    throw new Error("The pending Builder recovery marker no longer matches this Estimate Product.");
  }
}

function currentSignShopSessionToken() {
  try {
    if (typeof window === "undefined") return "";
    return String(window.localStorage?.getItem("sss_session_token") || "").trim();
  } catch {
    return "";
  }
}

export async function ensureBuilderPriceRevision(idempotencyKey, revision) {
  const sessionToken = currentSignShopSessionToken();
  if (!sessionToken) {
    throw new Error("Your signed sign-shop session is no longer available. Sign in again before changing Builder pricing.");
  }
  const response = await base44.functions.invoke("ensureBuilderPriceRevision", {
    idempotency_key: idempotencyKey,
    revision,
    session_token: sessionToken,
  });
  const result = response?.data || response;
  if (result?.error) throw new Error(result.error);
  if (!result?.revision?.id) throw new Error("Builder price revision could not be verified after recording.");
  return result.revision;
}

async function applyPendingSourcePatch(pending) {
  const sourceEntity = String(pending?.source_entity || "").trim();
  const sourceProjectId = String(pending?.source_project_id || "").trim();
  const sourcePatch = pending?.source_patch && typeof pending.source_patch === "object" ? pending.source_patch : null;
  if (!sourceEntity || !sourceProjectId || !sourcePatch || Object.keys(sourcePatch).length === 0) return null;
  const entity = staffEntities[sourceEntity];
  if (!entity?.get || !entity?.updateMany) throw new Error("The Builder source entity needed for recovery is unavailable.");
  const current = await entity.get(sourceProjectId);
  if (!current) throw new Error("The Builder source project could not be verified while recovering the pending mutation.");
  if (!recoveryPatchDiffers(current, sourcePatch)) return current;

  const expected = String(pending?.source_updated_date_before || "").trim();
  const actual = String(current?.updated_date || "").trim();
  if (expected && actual && expected !== actual) {
    throw new Error("The Builder source project changed while reattachment was pending. The recovery marker was retained and no unrelated source edit was overwritten.");
  }
  return replaceEntityFieldsIfUnchanged({
    entity,
    id: sourceProjectId,
    expectedUpdatedAt: current.updated_date || "",
    expectedFields: expectedEntityFields(current, sourcePatch),
    nextFields: sourcePatch,
    label: "Builder source recovery",
  });
}

async function applyPendingGroupCreatePlan(pending, builderProductId) {
  const plan = pending?.group_create_plan;
  const groups = Array.isArray(plan?.groups) ? plan.groups : [];
  if (!groups.length) return new Map();

  const currentGroups = await loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder recovery Part Groups" });
  if (!Array.isArray(currentGroups) || currentGroups.some((group) => String(group?.builder_product_id || "") !== String(builderProductId || ""))) {
    throw new Error("Part Groups could not be verified while recovering the pending Builder mutation.");
  }
  const byKey = new Map(currentGroups.map((group) => [group.group_key, group]));
  const resolvedIds = new Map();

  for (const step of groups) {
    const groupKey = String(step?.group_key || step?.data?.group_key || "").trim();
    const data = step?.data && typeof step.data === "object" ? step.data : null;
    if (!groupKey || !data) throw new Error("A stored Part Group create step is invalid. Recovery was stopped before creating anything else.");
    const { record: resolved } = await createBuilderPartGroupWithRecovery({
      entity: staffEntities.BuilderPartGroup,
      data,
      label: `Builder Part Group “${data.group_name || groupKey}” recovery create`,
    });
    if (!resolved?.id) throw new Error("A Part Group could not be verified after creation while recovering the Builder mutation.");
    byKey.set(groupKey, resolved);
    resolvedIds.set(groupKey, resolved.id);
  }
  return resolvedIds;
}

function resolvePendingPartGroupRefs(plan, groupIds) {
  if (!Array.isArray(plan?.part_updates) || !groupIds?.size) return plan;
  return {
    ...plan,
    part_updates: plan.part_updates.map((step) => {
      const groupKey = String(step?.part_group_key_ref || "").trim();
      if (!groupKey) return step;
      const groupId = groupIds.get(groupKey);
      if (!groupId) throw new Error("A stored Part could not resolve its pending Part Group during recovery.");
      return {
        ...step,
        data: step?.data ? { ...step.data, part_group_id: groupId } : step.data,
        patch: step?.patch ? { ...step.patch, part_group_id: groupId } : step.patch,
      };
    }),
  };
}

async function verifyPendingPreconditions(pending, builderProductId) {
  const plan = pending?.precondition_plan;
  if (!plan || typeof plan !== "object") return;

  const createGroups = Array.isArray(pending?.group_create_plan?.groups) ? pending.group_create_plan.groups : [];
  let createdGroupsByKey = new Map();
  if (createGroups.length) {
    const currentGroups = await loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder recovery Part Groups" });
    if (!Array.isArray(currentGroups)) throw new Error("Part Groups could not be verified while checking Builder mutation preconditions.");
    createdGroupsByKey = new Map(currentGroups.map((group) => [group.group_key, group]));
  }

  for (const step of plan.groups || []) {
    const group = await staffEntities.BuilderPartGroup.get(step.id);
    if (!group) {
      if (step.allow_missing_if_applied) continue;
      throw new Error("A source Part Group disappeared while the Builder mutation was pending.");
    }
    if (String(group.builder_product_id || "") !== String(builderProductId || "")) {
      throw new Error("A source Part Group changed ownership while the Builder mutation was pending.");
    }
    const sourceMatches =
      (!step.expected_patch || !recoveryPatchDiffers(group, step.expected_patch)) &&
      (!step.expected_updated_date || !group.updated_date || String(step.expected_updated_date) === String(group.updated_date));
    if (sourceMatches) continue;
    if (step.target_patch && !recoveryPatchDiffers(group, step.target_patch)) continue;
    throw new Error(`Part Group “${group.group_name || "Part Group"}” changed while the Builder mutation was pending. No unrelated Group edit was overwritten.`);
  }

  for (const step of plan.parts || []) {
    const part = await staffEntities.BuilderPart.get(step.id);
    if (!part || String(part.builder_product_id || "") !== String(builderProductId || "")) {
      throw new Error("A source Part changed ownership or disappeared while the Builder mutation was pending.");
    }
    const sourceMatches =
      (!step.expected_patch || !recoveryPatchDiffers(part, step.expected_patch)) &&
      (!step.expected_updated_date || !part.updated_date || String(step.expected_updated_date) === String(part.updated_date));
    if (sourceMatches) continue;
    if (step.target_patch && !recoveryPatchDiffers(part, step.target_patch)) continue;
    if (step.target_group_key_ref) {
      const targetGroup = createdGroupsByKey.get(step.target_group_key_ref);
      if (targetGroup?.id && String(part.part_group_id || "") === String(targetGroup.id)) continue;
    }
    throw new Error(`Part “${part.part_name || "Part"}” changed while the Builder mutation was pending. No unrelated Part edit was overwritten.`);
  }
}

async function applyPendingDeletePlan(pending, builderProductId) {
  const plan = pending?.delete_plan;
  if (!plan || typeof plan !== "object") return { partDeletes: 0, groupDeletes: 0 };

  // Verify every surviving delete target before deleting any of them. This keeps
  // a concurrent Part Group edit from being discovered only after the Part has
  // already been removed. Missing targets are treated as already-applied steps.
  const verifiedParts = [];
  const verifiedGroups = [];
  for (const step of plan.parts || []) {
    const part = await staffEntities.BuilderPart.get(step.id);
    if (!part) continue;
    if (String(part.builder_product_id || "") !== String(builderProductId || "")) {
      throw new Error("A Part scheduled for deletion changed ownership while the Builder mutation was pending.");
    }
    const expected = String(step.expected_updated_date || "").trim();
    const current = String(part.updated_date || "").trim();
    if (expected && current && expected !== current) {
      throw new Error(`Part “${part.part_name || "Part"}” changed while removal was pending. No unrelated Part edit was deleted.`);
    }
    verifiedParts.push(part);
  }
  for (const step of plan.groups || []) {
    const group = await staffEntities.BuilderPartGroup.get(step.id);
    if (!group) continue;
    if (String(group.builder_product_id || "") !== String(builderProductId || "")) {
      throw new Error("A Part Group scheduled for deletion changed ownership while the Builder mutation was pending.");
    }
    const expected = String(step.expected_updated_date || "").trim();
    const current = String(group.updated_date || "").trim();
    if (expected && current && expected !== current) {
      throw new Error(`Part Group “${group.group_name || "Part Group"}” changed while removal was pending. No unrelated group edit was deleted.`);
    }
    verifiedGroups.push(group);
  }

  let partDeletes = 0;
  let groupDeletes = 0;
  for (const part of verifiedParts) {
    await deleteBuilderEntityIfUnchanged({
      entity: staffEntities.BuilderPart,
      record: part,
      guardFields: { builder_product_id: builderProductId },
      label: `Builder Part “${part.part_name || "Part"}”`,
    });
    partDeletes += 1;
  }
  for (const group of verifiedGroups) {
    await deleteBuilderEntityIfUnchanged({
      entity: staffEntities.BuilderPartGroup,
      record: group,
      guardFields: { builder_product_id: builderProductId },
      label: `Builder Part Group “${group.group_name || "Part Group"}”`,
    });
    groupDeletes += 1;
  }
  return { partDeletes, groupDeletes };
}

export async function resumeBuilderMutation({
  estimateId,
  estimate,
  builder,
  parts,
  line,
  pending,
  applyPartPlan,
}) {
  validatePendingBuilderMutation(pending, { estimateId, builder, line });
  if (pending.kind === "builder_part_group_move") {
    throw new Error("This pending Part Group move must be resumed with its two-Product recovery action.");
  }
  if (pending.kind === "builder_product_remove") {
    throw new Error("This pending Product removal must be resumed with Resume Product Remove.");
  }
  if (typeof applyPartPlan !== "function") throw new Error("Builder recovery could not apply its stored Part plan.");
  await assertEstimateProductMutationAllowed(estimate, { allowPriceAcceptanceKey: pending.key });

  if (!Array.isArray(parts) || parts.some((part) => part?.builder_product_id !== builder.id)) {
    throw new Error("Builder Parts could not be verified while recovering the pending Builder mutation.");
  }
  const plan = pending.part_acceptance_plan || {};
  const builderPatch = pending.builder_patch || {};
  const preflightBuilder = await staffEntities.BuilderProduct.get(builder.id);
  if (!preflightBuilder?.id) throw new Error("Builder Product could not be verified before recovering the pending mutation.");
  if (recoveryPatchDiffers(preflightBuilder, builderPatch)) {
    const expectedBuilderUpdatedAt = String(pending.builder_updated_date_before || "").trim();
    const currentBuilderUpdatedAt = String(preflightBuilder.updated_date || "").trim();
    if (expectedBuilderUpdatedAt && currentBuilderUpdatedAt && expectedBuilderUpdatedAt !== currentBuilderUpdatedAt) {
      throw new Error("This Builder Product changed while a Builder mutation was pending. Recovery stopped before applying any stored Part/Group writes.");
    }
  }
  await verifyPendingPreconditions(pending, builder.id);
  await applyPendingSourcePatch(pending);
  await applyPendingDeletePlan(pending, builder.id);
  const groupIds = await applyPendingGroupCreatePlan(pending, builder.id);
  const resolvedPlan = resolvePendingPartGroupRefs(plan, groupIds);
  // Re-read Parts inside the applier instead of trusting the post-marker snapshot.
  // This closes the race where another session edits a Part after marker verification
  // but before the exact stored Part patch is written.
  await applyPartPlan(builder.id, resolvedPlan);
  if (pending.post_part_delete_plan) {
    await applyPendingDeletePlan({ delete_plan: pending.post_part_delete_plan }, builder.id);
  }

  let revision = pending.revision || {};
  const changedParts = Array.isArray(revision.changed_parts) ? revision.changed_parts : [];
  if (changedParts.some((part) => part?.part_key_ref || part?.new_group_key_ref)) {
    const currentParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder recovery Parts" });
    if (!Array.isArray(currentParts)) throw new Error("Created Parts could not be verified before recording the Builder revision.");
    const partsByKey = new Map(currentParts.map((part) => [part.part_key, part]));
    revision = {
      ...revision,
      changed_parts: changedParts.map((part) => {
        const hydrated = { ...part };
        if (hydrated.part_key_ref) {
          const createdPart = partsByKey.get(hydrated.part_key_ref);
          if (!createdPart?.id) throw new Error("A created Part could not be resolved for the Builder revision audit.");
          hydrated.part_id = createdPart.id;
          hydrated.part_key = createdPart.part_key;
          delete hydrated.part_key_ref;
        }
        if (hydrated.new_group_key_ref) {
          const createdGroupId = groupIds.get(hydrated.new_group_key_ref);
          if (!createdGroupId) throw new Error("A created Part Group could not be resolved for the Builder revision audit.");
          hydrated.new_group_id = createdGroupId;
          delete hydrated.new_group_key_ref;
        }
        return hydrated;
      }),
    };
  }
  if (!pending.skip_revision) {
    await ensureBuilderPriceRevision(pending.key, revision);
  }

  const currentBuilder = await staffEntities.BuilderProduct.get(builder.id);
  if (!currentBuilder?.id) throw new Error("Builder Product could not be verified while completing the pending mutation.");
  if (recoveryPatchDiffers(currentBuilder, builderPatch)) {
    const expectedBuilderUpdatedAt = String(pending.builder_updated_date_before || "").trim();
    const currentBuilderUpdatedAt = String(currentBuilder.updated_date || "").trim();
    if (expectedBuilderUpdatedAt && currentBuilderUpdatedAt && expectedBuilderUpdatedAt !== currentBuilderUpdatedAt) {
      throw new Error("This Builder Product changed while a Builder mutation was pending. The recovery marker was retained and no unrelated Builder edit was overwritten.");
    }
    await replaceBuilderEntityFieldsIfUnchanged({
      entity: staffEntities.BuilderProduct,
      id: builder.id,
      expectedUpdatedAt: currentBuilder.updated_date || "",
      expectedFields: expectedBuilderEntityFields(currentBuilder, builderPatch),
      nextFields: builderPatch,
      guardFields: { estimate_id: currentBuilder.estimate_id },
      label: "Builder Product recovery completion",
    });
  }

  const latestEstimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!latestEstimate) throw new Error("Estimate could not be verified while completing the pending Builder mutation.");
  const latestLine = (latestEstimate.line_items || []).find((item) => item.builder_product_id === builder.id);
  if (!latestLine) throw new Error("This Product is no longer part of the estimate. The pending Builder recovery marker could not be completed.");
  const latestPending = pendingBuilderMutation(latestLine);
  const linePatch = pending.line_patch || {};

  if (!latestPending) {
    if (!recoveryPatchDiffers(latestLine, linePatch)) {
      return {
        blocked: false,
        recovered: true,
        alreadyCompleted: true,
        changedParts: resolvedPlan.changed_parts || [],
        line: latestLine,
      };
    }
    throw new Error("The Builder recovery marker disappeared before the accepted Estimate line was verified. Reload before continuing.");
  }
  if (latestPending.key !== pending.key) {
    throw new Error("A different Builder recovery operation is now active for this Product. Reload before continuing.");
  }
  await assertEstimateProductMutationAllowed(latestEstimate, { allowPriceAcceptanceKey: pending.key });

  const lineItems = (latestEstimate.line_items || []).map((item) =>
    item.builder_product_id === builder.id
      ? { ...item, ...linePatch, price_acceptance_pending: {} }
      : item
  );
  const updateResult = await replaceEstimateFieldsIfUnchanged({
    entity: staffEntities.AllInOneEstimate,
    estimateId,
    expectedFields: expectedEstimateFields(latestEstimate, { line_items: lineItems }),
    nextFields: { line_items: lineItems },
    label: "Builder mutation recovery completion",
  });
  const completedLine = (updateResult?.line_items || lineItems).find((item) => item.builder_product_id === builder.id) || null;
  return {
    blocked: false,
    recovered: true,
    changedParts: resolvedPlan.changed_parts || [],
    line: completedLine,
  };
}

import { assertEstimateProductMutationAllowed } from "@/components/estimator/estimateMutationGuard";
import { staffEntities } from "@/components/staff/staffEntities";

// String fields can differ only by stray or repeated whitespace; normalize
// whitespace (but not case) so stored rows match their intended patches.
const cleanString = (value) => String(value ?? "").trim().replace(/\s+/g, " ");

function normalize(value) {
  if (Array.isArray(value)) return value.map(normalize);
  if (!value || typeof value !== "object") return value;
  return Object.keys(value).sort().reduce((out, key) => {
    // Values compared here are individual patch fields, not whole entity rows.
    // Preserve nested ids and metadata because they can be substantive Builder
    // item identity inside arrays/objects.
    out[key] = normalize(value[key]);
    return out;
  }, {});
}

function sameValue(a, b) {
  if (a !== null && a !== undefined && a !== "" && b !== null && b !== undefined && b !== "") {
    if (Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
      return Math.abs(Number(a) - Number(b)) <= 0.000001;
    }
  }
  if (typeof a === "string" && typeof b === "string") {
    return cleanString(a) === cleanString(b);
  }
  return JSON.stringify(normalize(a)) === JSON.stringify(normalize(b));
}

export function sourcePatchMatches(record, patch) {
  if (!record || !patch) return false;
  return Object.entries(patch).every(([key, value]) => sameValue(record?.[key], value));
}

export async function preflightBuilderSourceMutation({ estimateId = "" } = {}) {
  if (!estimateId) return null;
  const estimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!estimate?.id) throw new Error("Estimate could not be verified before saving this Builder source.");
  await assertEstimateProductMutationAllowed(estimate);
  return estimate;
}

export async function updateBuilderSourceProject({
  entity,
  sourceId,
  expectedUpdatedAt,
  data,
  estimateId = "",
  label = "Builder source project",
}) {
  if (!entity?.updateMany || !entity?.get || !sourceId) {
    throw new Error(`${label} could not initialize its concurrency-safe update.`);
  }
  const expected = String(expectedUpdatedAt || "").trim();
  if (!expected) {
    throw new Error(`${label} is missing its loaded version. Reload it before saving.`);
  }

  await preflightBuilderSourceMutation({ estimateId });

  const verified = (record) => !!record && record.id === sourceId
    && typeof record.updated_date === "string" && record.updated_date.length > 0
    && sourcePatchMatches(record, data);
  const conflict = () => new Error(`${label} changed in another session. Reload it before saving.`);

  let result;
  try {
    result = await entity.updateMany(
      { id: sourceId, updated_date: expected },
      { $set: data },
    );
  } catch (error) {
    const current = await entity.get(sourceId).catch(() => null);
    if (verified(current)) return current;
    throw error;
  }

  if (!result || !Number.isInteger(result.updated) || (result.updated !== 0 && result.updated !== 1)) {
    throw new Error(`${label} conditional-update result could not be verified.`);
  }

  if (result.updated === 1) {
    const saved = await entity.get(sourceId).catch(() => null);
    if (!saved) throw new Error(`${label} was updated but could not be re-read.`);
    if (!verified(saved)) throw conflict();
    return saved;
  }

  const current = await entity.get(sourceId).catch(() => null);
  if (verified(current)) {
    // Exact retry after a lost successful response. Do not rewrite the row merely
    // to refresh its timestamp; reuse the already-persisted intended state.
    return current;
  }

  throw conflict();
}

import { deleteEntityIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// Read-after-write grace for the post-create verify read: a create whose
// response was lost can still have landed, and an immediate empty verify
// read is not conclusive.
const VERIFY_RETRY_DELAY_MS = 700;

const canonicalRecord = (rows = []) => [...rows].sort((a, b) => {
  const aStamp = String(a?.created_date || "");
  const bStamp = String(b?.created_date || "");
  if (aStamp !== bStamp) return aStamp.localeCompare(bStamp);
  return String(a?.id || "").localeCompare(String(b?.id || ""));
})[0] || null;

function normalize(value) {
  if (Array.isArray(value)) return value.map(normalize);
  if (!value || typeof value !== "object") return value;
  return Object.keys(value).sort().reduce((out, key) => {
    out[key] = normalize(value[key]);
    return out;
  }, {});
}

function sameValue(a, b) {
  const emptyA = a === undefined || a === null || a === "";
  const emptyB = b === undefined || b === null || b === "";
  if (emptyA && emptyB) return true;
  if (!emptyA && !emptyB && Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
    return Math.abs(Number(a) - Number(b)) <= 0.000001;
  }
  // Trimmed server values must match the retry payload — backend `clean()`
  // trims most string fields on write, so a strict compare would false-negative
  // a legitimately-reused record and 409 "retry key belongs to different data".
  if (typeof a === "string" && typeof b === "string") return a.trim() === b.trim();
  return JSON.stringify(normalize(a)) === JSON.stringify(normalize(b));
}

function matchesPayload(row, payload) {
  return !!row && Object.entries(payload || {}).every(([field, value]) => sameValue(row[field], value));
}

export function newCreationRequestKey(prefix = "create") {
  const token = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `${String(prefix || "create").trim()}:${token}`;
}

export async function ensureIdempotentEntityCreate({
  entity,
  keyField = "idempotency_key",
  key,
  data,
  label = "Record",
} = {}) {
  const cleanField = String(keyField || "").trim();
  const cleanKey = String(key || "").trim();
  if (!entity?.filter || !entity?.create || !cleanField || !cleanKey) {
    throw new Error(`${label} could not initialize its retry-safe create.`);
  }

  const payload = { ...data, [cleanField]: cleanKey };
  const load = async () => {
    const rows = await entity.filter({ [cleanField]: cleanKey });
    if (!Array.isArray(rows)) throw new Error(`${label} retry state could not be verified.`);
    return rows.filter((row) => String(row?.[cleanField] || "").trim() === cleanKey);
  };

  const existing = await load();
  if (existing.length > 1) {
    throw new Error(`${label} already has multiple records with this retry key. No row was deleted; reload and review the duplicates before continuing.`);
  }
  if (existing.length === 1) {
    if (!matchesPayload(existing[0], payload)) {
      throw new Error(`${label} retry key already belongs to a record with different data. No row was changed.`);
    }
    return existing[0];
  }

  let created = null;
  let createError = null;
  try {
    created = await entity.create(payload);
  } catch (error) {
    createError = error;
  }

  let afterCreate = null;
  let verifyError = null;
  try {
    afterCreate = await load();
  } catch (error) {
    verifyError = error;
  }
  // Read-after-write lag: a create that failed at the response layer can
  // still have landed, so an immediate empty/failed verify is not conclusive.
  // Give the write a moment and re-read once before declaring the outcome
  // unknown — a retry must resolve the existing row, never create a dup.
  if ((!Array.isArray(afterCreate) || afterCreate.length === 0) && (createError || !created?.id)) {
    await sleep(VERIFY_RETRY_DELAY_MS);
    try {
      const retryRows = await load();
      if (Array.isArray(retryRows)) afterCreate = retryRows;
    } catch (error) {
      verifyError = verifyError || error;
    }
  }
  if (!Array.isArray(afterCreate)) {
    if (created?.id && matchesPayload(created, payload)) return created;
    throw new Error(`${label} create outcome could not be verified. Do not retry blindly; reload first. ${verifyError?.message || "Recovery lookup failed."}`);
  }

  if (afterCreate.length === 1) {
    // Our create returned an id but the only visible same-key row is a
    // different record — a concurrent create landed too and ours is still
    // indexing. Fail closed instead of silently orphaning our row as a dup.
    if (created?.id && String(afterCreate[0].id) !== String(created.id)) {
      throw new Error(`${label} was created concurrently more than once. No uncertain duplicate was deleted; reload and review records with this retry key.`);
    }
    if (!matchesPayload(afterCreate[0], payload)) {
      throw new Error(`${label} retry key exists but its live data does not match this create. No row was changed or deleted.`);
    }
    return afterCreate[0];
  }

  if (afterCreate.length > 1) {
    const keep = canonicalRecord(afterCreate);
    const ours = created?.id ? afterCreate.find((row) => row.id === created.id) : null;
    if (ours && ours.id !== keep?.id && matchesPayload(ours, payload)) {
      await deleteEntityIfUnchanged({
        entity,
        record: ours,
        guardFields: { [cleanField]: cleanKey },
        label: `${label} losing retry duplicate`,
      });
      const finalRows = await load();
      if (finalRows.length === 1 && finalRows[0]?.id === keep?.id && matchesPayload(finalRows[0], payload)) {
        return finalRows[0];
      }
    }
    throw new Error(`${label} was created concurrently more than once. No uncertain duplicate was deleted; reload and review records with this retry key.`);
  }

  if (created?.id && matchesPayload(created, payload)) return created;
  if (createError) {
    throw new Error(`${label} create failed and no matching record was visible on recovery read. Do not retry blindly; reload first. ${createError?.message || ""}`.trim());
  }
  throw new Error(`${label} create response could not be verified. Do not retry blindly; reload first.`);
}

const DEFAULT_PAGE_SIZE = 500;
const DEFAULT_MAX_ROWS = 50000;
const RATE_LIMIT_MAX_RETRIES = 3;
const RATE_LIMIT_BASE_DELAY_MS = 1200;

function rowIdentity(row, index) {
  const id = String(row?.id || "").trim();
  return id || `__row_${index}`;
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export function isRateLimitError(error) {
  const status = error?.status ?? error?.response?.status;
  if (status === 429) return true;
  const message = String(
    error?.message ||
    error?.response?.data?.error ||
    error?.data?.error ||
    ""
  ).toLowerCase();
  return message.includes("rate limit") || message.includes("too many requests");
}

/**
 * Retries a single SDK call when the platform returns a transient rate-limit
 * error. Uses exponential backoff so concurrent page-load calls (builder
 * reconciliation, part catalogs, section snapshots) don't all retry at once.
 */
export async function withRateLimitRetry(fn) {
  for (let attempt = 0; attempt <= RATE_LIMIT_MAX_RETRIES; attempt += 1) {
    try {
      return await fn();
    } catch (error) {
      // The request governor already retried this call with backoff; a second
      // retry loop here would multiply the delay without helping.
      if (typeof error?.ccsGovernorRetried === "number") throw error;
      if (attempt < RATE_LIMIT_MAX_RETRIES && isRateLimitError(error)) {
        await sleep(RATE_LIMIT_BASE_DELAY_MS * Math.pow(2, attempt));
        continue;
      }
      throw error;
    }
  }
}

/**
 * Load a complete estimator prerequisite catalog without relying on Base44's
 * list/filter default limit (50 rows).
 *
 * This helper is intentionally read-only. It pages the existing entity client
 * using the SDK's list/filter(sort, limit, skip) contract, fails closed on an
 * unreadable page, and de-duplicates by entity id so callers never silently
 * estimate from a partial catalog.
 *
 * Paging order defaults to ASCENDING "created_date" (not "-created_date").
 * That is deliberate: new rows append to the end of the set, so earlier
 * skip/limit pages stay stable while a full scan is in flight — a
 * newest-first order would shift every page on each concurrent insert.
 * Callers may pass any SDK sort string; it is forwarded to list/filter on
 * every page (an empty/falsy sort falls back to the SDK's own default).
 */
/**
 * @param {{
 *   entity?: any,
 *   query?: Record<string, any> | null,
 *   sort?: string | null,
 *   pageSize?: number,
 *   maxRows?: number,
 *   label?: string,
 *   limit?: number | null,
 * }} [options]
 */
// Short-TTL in-memory cache for slow-changing catalogs (jurisdiction/locality
// lists). Opt-in per call — repeated mounts of the same page stop re-reading
// the whole catalog and burning the shared rate-limit budget. Keyed per
// entity object (like inFlightReads): the query/sort/limits tuple alone is
// not unique — two entities with identical reads would otherwise share a
// cache slot and serve each other's rows.
const readCache = new WeakMap(); // entity -> Map<key, {at, rows}>
const CACHE_MAX_AGE_MS = 30000;
// Identical reads issued at the same instant (mount bursts, StrictMode double
// mounts, sibling components) share one network pass. Keyed per entity object
// so different gateways never share rows; every caller receives a copy so an
// in-place sort/splice by one consumer cannot corrupt another's result.
const inFlightReads = new WeakMap(); // entity -> Map<key, Promise<rows>>

const readCacheBucket = (entity) => {
  let bucket = readCache.get(entity);
  if (!bucket) {
    bucket = new Map();
    readCache.set(entity, bucket);
  }
  return bucket;
};

// Seed the short-TTL cache with rows fetched through a batch read so the
// per-entity loaders skip their own network call on the next mount.
export const primeEntityRowsCache = (entity, query, sort, rows) => {
  if (entity === null || (typeof entity !== "object" && typeof entity !== "function")) return;
  readCacheBucket(entity).set(JSON.stringify([query ?? null, sort, DEFAULT_PAGE_SIZE, DEFAULT_MAX_ROWS]), { at: Date.now(), rows });
};

export async function loadAllEntityRows({
  entity,
  query = null,
  sort = "created_date",
  pageSize = DEFAULT_PAGE_SIZE,
  maxRows = DEFAULT_MAX_ROWS,
  label = "Estimator prerequisite catalog",
  cacheTtlMs = 0,
  // (#403) `limit` bounds the total rows returned for callers that only need a
  // window (e.g. "the 50 newest"), not a verified-complete catalog. Reaching
  // the bound is a normal truncation — unlike `maxRows`, which stays a
  // runaway-scan safety net and still throws when a full scan would pass it.
  limit = null,
} = {}) {
  const parsedLimit = limit == null ? null : Math.floor(Number(limit));
  const safeLimit = Number.isFinite(parsedLimit) && parsedLimit > 0 ? parsedLimit : null;
  const canShare = entity !== null && (typeof entity === "object" || typeof entity === "function");
  const cacheKey = cacheTtlMs > 0 && canShare ? JSON.stringify([query, sort, pageSize, safeLimit ?? maxRows]) : null;
  if (cacheKey) {
    const hit = readCache.get(entity)?.get(cacheKey);
    if (hit && Date.now() - hit.at < Math.min(cacheTtlMs, CACHE_MAX_AGE_MS)) return [...hit.rows];
  }
  const hasFilter = query && typeof query === "object";
  const reader = hasFilter ? entity?.filter : entity?.list;
  if (typeof reader !== "function") {
    throw new Error(`${label} could not initialize its paged read.`);
  }

  const safePageSize = Math.max(1, Math.min(500, Number(pageSize) || DEFAULT_PAGE_SIZE));
  // A bounded read never fetches a page larger than the rows still wanted —
  // `limit: 50` costs exactly one 50-row request, not a 500-row page.
  const safeMaxRows = safeLimit ?? Math.max(safePageSize, Number(maxRows) || DEFAULT_MAX_ROWS);

  // Join an identical read already in flight instead of starting a second
  // paged scan for the same data. Non-object entities skip sharing.
  const flightKey = JSON.stringify([hasFilter ? "filter" : "list", query ?? null, sort ?? null, safePageSize, safeMaxRows]);
  if (canShare) {
    const existing = inFlightReads.get(entity)?.get(flightKey);
    if (existing) return existing.then((rows) => [...rows]);
  }

  const readPromise = (async () => {
    const collected = [];
    const seen = new Set();
    let skip = 0;

    while (skip < safeMaxRows) {
      const pageLimit = Math.min(safePageSize, safeMaxRows - skip);
      const page = await withRateLimitRetry(() =>
        hasFilter
          ? entity.filter(query, sort || undefined, pageLimit, skip)
          : entity.list(sort || undefined, pageLimit, skip)
      );

      if (!Array.isArray(page)) {
        throw new Error(`${label} could not be verified completely. Estimating was blocked rather than using a partial catalog.`);
      }

      for (let index = 0; index < page.length; index += 1) {
        const row = page[index];
        const key = rowIdentity(row, skip + index);
        if (seen.has(key)) continue;
        seen.add(key);
        collected.push(row);
      }

      if (page.length < pageLimit) {
        if (cacheKey) readCacheBucket(entity).set(cacheKey, { at: Date.now(), rows: collected });
        return collected;
      }
      skip += pageLimit;
    }

    if (safeLimit != null) {
      if (cacheKey) readCacheBucket(entity).set(cacheKey, { at: Date.now(), rows: collected });
      return collected;
    }
    throw new Error(`${label} exceeds the ${safeMaxRows.toLocaleString()}-record estimator safety limit.`);
  })();

  if (!canShare) return readPromise;
  let flightBucket = inFlightReads.get(entity);
  if (!flightBucket) {
    flightBucket = new Map();
    inFlightReads.set(entity, flightBucket);
  }
  flightBucket.set(flightKey, readPromise);
  try {
    const rows = await readPromise;
    return [...rows];
  } finally {
    if (flightBucket.get(flightKey) === readPromise) flightBucket.delete(flightKey);
  }
}

import { isEstimateProtected } from "@/components/estimator/estimateLifecycle";
import { getOpenEstimateRevision } from "@/components/estimator/estimateRevisionService";

/**
 * Server-backed gate for Product/Part mutations that can be triggered from
 * long-lived dialogs. The UI's readOnly state is not sufficient because the
 * estimate may have changed lifecycle state in another browser session.
 *
 * draft/calculated: editable normally
 * sent/approved: editable only while an EstimateRevision is open
 * archived/cancelled: permanently locked (unarchive/restore happens through
 *   the status lifecycle, never through a Product or Part mutation)
 */
// Stale pendings must not block mutations forever — if a Builder recovery was
// abandoned mid-operation more than 24h ago, treat its pending entry as expired
// so the user isn't permanently locked out of the estimate.
const PENDING_TTL_MS = 24 * 60 * 60 * 1000;

export function getPendingEstimatePriceAcceptance(estimate) {
  const line = (estimate?.line_items || []).find((item) => {
    const pending = item?.price_acceptance_pending;
    if (!String(pending?.key || "").trim()) return false;
    const startedAt = Date.parse(pending?.started_at || "");
    if (Number.isFinite(startedAt) && Date.now() - startedAt > PENDING_TTL_MS) return false;
    return true;
  });
  return line ? { line, pending: line.price_acceptance_pending } : null;
}

export async function assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt = "", allowPriceAcceptanceKey = "" } = {}) {
  if (!estimate?.id) throw new Error("Estimate could not be verified for this change.");
  const expected = String(expectedUpdatedAt || "").trim();
  const current = String(estimate.updated_date || "").trim();
  if (expected && current !== expected) {
    throw new Error("This estimate changed in another session. Reload it before changing Products or Parts.");
  }
  const allowedKey = String(allowPriceAcceptanceKey || "").trim();
  const pendingEntry = getPendingEstimatePriceAcceptance(estimate);
  const pendingKey = String(pendingEntry?.pending?.key || "").trim();
  if (pendingKey && pendingKey !== allowedKey) {
    throw new Error("A Builder mutation is still being recovered for this Product. Resume that operation before changing Products or Parts.");
  }
  if (estimate.deleted === true) {
    throw new Error("This estimate is in Trash. Restore it before changing Products or Parts.");
  }
  const status = String(estimate.status || "draft");
  if (status === "cancelled") {
    throw new Error("This estimate is cancelled and permanently locked. Product or Part changes cannot be added.");
  }
  if (status === "archived") {
    throw new Error("This estimate is archived and locked. Restore it to an active status before changing Products or Parts.");
  }
  if (!isEstimateProtected(status)) return null;

  const revision = await getOpenEstimateRevision(estimate.id);
  if (!revision) {
    throw new Error(`This estimate is ${status} and protected. Start an Estimate Revision before adding Products or Parts.`);
  }
  return revision;
}

import { invokeFleet, isFleetCoolingDown } from "@/components/fleet/fleetInvoke";
import { getSessionToken } from "@/components/auth/EmailGate";
import { noteRateLimit } from "@/api/rateLimitCooldown";

// Read facade for role-gated non-Fleet entities. Staff sessions are EmailGate
// sessions and cannot satisfy entity RLS directly, so reads route through the
// session-authenticated staffDataRead gateway (reads) and staffEntityWrite
// gateway (writes). Write methods reach only the entity/operation pairs the
// backend allowlist permits; anything else is rejected server-side.
// --- Mount-storm coalescing ---------------------------------------------------------
// A page mount fires a dozen parallel reads through this facade; previously each
// became its own staffDataRead invoke on the shared service budget. Calls made in
// the same synchronous burst now coalesce into one batch invoke (the gateway
// supports up to 16 entities per call), and identical simultaneous reads share a
// single request entirely.
// Guests (no EmailGate session) must never reach the gateways — every call
// is a guaranteed 401 that burns budget and spams the console.
const hasSession = () => !!getSessionToken();
const NO_SESSION_ERR = () => new Error("Sign-in required");

// Per-session negative cache of denied entities. Once the gateway refuses an
// entity for this session (403), every repeat read is a guaranteed failure
// that only spends the shared budget — resolve it locally until the session
// token changes (a different signed-in user may have different access).
let deniedSessionToken;
const deniedEntities = new Set();
const syncDeniedScope = () => {
  const token = getSessionToken();
  if (token !== deniedSessionToken) {
    deniedEntities.clear();
    deniedSessionToken = token;
  }
};
const markDenied = (entity) => {
  if (!entity) return;
  syncDeniedScope();
  deniedEntities.add(entity);
};
const isDenied = (entity) => {
  syncDeniedScope();
  return deniedEntities.has(entity);
};
const isForbidden = (err) => Number(err?.status ?? err?.response?.status) === 403;

// Short-TTL positive cache for list/filter results. Page mounts re-read the
// same semi-static catalogs on every navigation; a 30s hit turns a remount
// into a free local read. Entries are keyed by session token so a sign-in
// change can never see another session's rows, and every successful write
// through this facade busts its entity's entries so the writer always
// re-reads fresh rows. Hits return a copy so in-place sorts cannot corrupt
// the cached array for other callers.
const READ_CACHE_TTL_MS = 30000;
const readCache = new Map();
const readCacheKey = (entity, args) => `${getSessionToken()}|${entity}|${JSON.stringify(args)}`;
const cachedRead = (key) => {
  const entry = readCache.get(key);
  if (!entry) return undefined;
  if (entry.expires <= Date.now()) { readCache.delete(key); return undefined; }
  return entry.value;
};
const cacheRead = (key, value) => {
  readCache.set(key, { value, expires: Date.now() + READ_CACHE_TTL_MS });
};
const bustReadCache = (entity) => {
  const marker = `|${entity}|`;
  for (const key of readCache.keys()) {
    if (key.includes(marker)) readCache.delete(key);
  }
};

// The platform's function client resolves with the transport envelope
// ({ status, data, ... }) rather than the JSON body, while a few call paths hand
// back the body itself. Normalize once here so every staff read/write in the app
// reads from the gateway's actual payload instead of silently finding nothing.
const bodyOf = (response) => {
  if (!response || typeof response !== "object") return {};
  const isEnvelope = Object.prototype.hasOwnProperty.call(response, "status")
    && Object.prototype.hasOwnProperty.call(response, "data");
  const body = isEnvelope ? response.data : response;
  return body && typeof body === "object" ? body : {};
};

// Callers use both the SDK-style options object ({sort, limit, skip}) and the
// positional (sort, limit, skip) contract. An options object must never land in
// the gateway's sort slot, and an options call answers with a page shape
// ({items, has_more, next_cursor}) like the platform SDK, while a positional
// call keeps returning a plain array.
function readArgs(sortOrOptions, limit, skip) {
  if (sortOrOptions && typeof sortOrOptions === "object" && !Array.isArray(sortOrOptions)) {
    return {
      paged: true,
      sort: sortOrOptions.sort,
      limit: sortOrOptions.limit,
      skip: sortOrOptions.skip ?? sortOrOptions.offset,
    };
  }
  return { paged: false, sort: sortOrOptions, limit, skip };
}

const asRows = (response) => {
  const rows = bodyOf(response).items;
  return Array.isArray(rows) ? rows : [];
};
const page = (rows) => ({ items: rows, has_more: false, next_cursor: null });

const pendingBatch = new Map();
let flushScheduled = false;
// queueMicrotask flushed after one tick, but sibling lazy chunks mount across
// several ticks — each landing became its own batch (~9 invokes per page
// mount). A short timer still reads as instant while merging those waves.
const BATCH_WINDOW_MS = 30;

const singleRead = (entity, args) =>
  invokeFleet("staffDataRead", { entity, ...args }).then(asRows, (err) => {
    if (isForbidden(err)) markDenied(entity);
    throw err;
  });

async function flushBatch() {
  flushScheduled = false;
  const entries = [...pendingBatch.values()];
  pendingBatch.clear();
  if (entries.length === 0) return;
  const batchable = [];
  const individual = [];
  const seen = new Set();
  for (const entry of entries) {
    // The batch response is keyed by entity name only, so an entity can appear
    // at most once per batch; extras fall back to direct reads.
    if (seen.has(entry.entity)) individual.push(entry);
    else { seen.add(entry.entity); batchable.push(entry); }
  }
  for (let i = 0; i < batchable.length; i += 16) {
    const chunk = batchable.slice(i, i + 16);
    try {
      // Each entry must carry its own entity name — the gateway rejects a batch
      // whose entries lack it, which used to fan every burst back out into
      // ~16 individual calls and saturate the function budget.
      const r = await invokeFleet("staffDataRead", { entities: chunk.map((e) => ({ entity: e.entity, ...e.args })) });
      const body = bodyOf(r);
      const out = body.entities || {};
      const errs = body.errors || {};
      // A 429 inside a batch still means the shared budget is saturated — the
      // invoke resolved, so base44Client never saw the limit; note it here.
      const limited = Object.values(errs).find((d) => Number(d?.status) === 429);
      if (limited) noteRateLimit(limited.retry_after_ms || body.retry_after_ms || 0);
      // Denied entities resolve as empty reads and go into the negative cache
      // so nothing in this session asks for them again.
      (body.denied || []).forEach(markDenied);
      chunk.forEach((e) => {
        if (errs[e.entity]) {
          const detail = errs[e.entity];
          if (Number(detail.status) === 403) markDenied(e.entity);
          e.reject(Object.assign(new Error(detail.error || 'Staff read failed'), { status: detail.status }));
        } else {
          e.resolve(Array.isArray(out[e.entity]) ? out[e.entity] : []);
        }
      });
    } catch (err) {
      // Rate-limited batch: fanning out into ~16 individual reads would amplify
      // the very saturation that caused the 429 — reject so callers degrade.
      if (err?.status === 429 || err?.response?.status === 429) {
        chunk.forEach((e) => e.reject(err));
      } else {
        // Non-429 whole-batch failure: retry the entries individually so the
        // healthy ones still resolve.
        individual.push(...chunk);
      }
    }
  }
  individual.forEach((e) => singleRead(e.entity, e.args).then(e.resolve, e.reject));
}

const batchedRead = (entity, args) => {
  if (!hasSession()) return Promise.resolve([]);
  const key = entity + "|" + JSON.stringify(args);
  const existing = pendingBatch.get(key);
  if (existing) return existing.promise;
  let resolveRef, rejectRef;
  const promise = new Promise((resolve, reject) => { resolveRef = resolve; rejectRef = reject; });
  pendingBatch.set(key, { entity, args, resolve: resolveRef, reject: rejectRef, promise });
  if (!flushScheduled) { flushScheduled = true; setTimeout(flushBatch, BATCH_WINDOW_MS); }
  return promise;
};

const METHODS = {
  filter: (entity, query, sortOrOptions, limit, skip) => {
    const args = readArgs(sortOrOptions, limit, skip);
    if (isDenied(entity)) return Promise.resolve(args.paged ? page([]) : []);
    const key = readCacheKey(entity, { query, sort: args.sort, limit: args.limit, skip: args.skip });
    const cached = cachedRead(key);
    if (cached !== undefined) return Promise.resolve(args.paged ? page(cached.slice()) : cached.slice());
    return batchedRead(entity, { query, sort: args.sort, limit: args.limit, skip: args.skip })
      .then((rows) => {
        cacheRead(key, rows);
        return args.paged ? page(rows) : rows;
      });
  },
  list: (entity, sortOrOptions, limit, skip) => {
    const args = readArgs(sortOrOptions, limit, skip);
    if (isDenied(entity)) return Promise.resolve(args.paged ? page([]) : []);
    const key = readCacheKey(entity, { sort: args.sort, limit: args.limit, skip: args.skip });
    const cached = cachedRead(key);
    if (cached !== undefined) return Promise.resolve(args.paged ? page(cached.slice()) : cached.slice());
    return batchedRead(entity, { sort: args.sort, limit: args.limit, skip: args.skip })
      .then((rows) => {
        cacheRead(key, rows);
        return args.paged ? page(rows) : rows;
      });
  },
  get: (entity, id) => {
    if (!hasSession() || isDenied(entity)) return Promise.resolve(null);
    return invokeFleet("staffDataRead", { entity, id }).then(
      (r) => bodyOf(r).item ?? null,
      (err) => { if (isForbidden(err)) markDenied(entity); throw err; },
    );
  },
  count: (entity, query, sortOrOptions, limit, skip) => {
    const args = readArgs(sortOrOptions, limit, skip);
    if (!hasSession() || isDenied(entity)) return Promise.resolve(0);
    return invokeFleet("staffDataRead", { entity, query, sort: args.sort, limit: args.limit, skip: args.skip, count: true }).then(
      (r) => bodyOf(r).count ?? 0,
      (err) => { if (isForbidden(err)) markDenied(entity); throw err; },
    );
  },
  create: (entity, data) =>
    hasSession() ? invokeFleet("staffEntityWrite", { entity, op: "create", data }).then((r) => { bustReadCache(entity); return bodyOf(r).record; }) : Promise.reject(NO_SESSION_ERR()),
  update: (entity, id, data) =>
    hasSession() ? invokeFleet("staffEntityWrite", { entity, op: "update", id, data }).then((r) => { bustReadCache(entity); return bodyOf(r).record; }) : Promise.reject(NO_SESSION_ERR()),
  updateMany: (entity, query, update) =>
    hasSession() ? invokeFleet("staffEntityWrite", { entity, op: "updateMany", id: query?.id, query, update }).then((r) => { bustReadCache(entity); return bodyOf(r).result; }) : Promise.reject(NO_SESSION_ERR()),
  delete: (entity, id) =>
    hasSession() ? invokeFleet("staffEntityWrite", { entity, op: "delete", id }).then((r) => { bustReadCache(entity); return bodyOf(r).deleted === true; }) : Promise.reject(NO_SESSION_ERR()),
  deleteMany: (entity, query) =>
    hasSession() ? invokeFleet("staffEntityWrite", { entity, op: "deleteMany", query }).then((r) => { bustReadCache(entity); return bodyOf(r).result; }) : Promise.reject(NO_SESSION_ERR()),
  // Staff sessions cannot use platform live-subscriptions (entity RLS is
  // backend-only), so subscribe polls staffDataRead and emits a synthetic
  // change event when the row set changes. Returns an unsubscribe function,
  // matching the SDK contract: `unsub = entity.subscribe(cb)`.
  subscribe: (entity, callback) => {
    if (typeof callback !== "function") return () => {};
    let stopped = false;
    let last = "";
    const check = async () => {
      // M-05: no entity traffic while the tab is hidden — this one guard covers
      // every subscribe() consumer app-wide (WO board, SalesFilter, etc.).
      if (typeof document !== "undefined" && document.hidden) return;
      if (!hasSession() || isDenied(entity) || isFleetCoolingDown()) return;
      try {
        // -updated_date puts mutations into the 50 most-recently-updated rows —
        // an unsorted default order would cap the digest to the oldest rows and
        // silently drop change events for anything past position 50.
        const r = await invokeFleet("staffDataRead", { entity, limit: 50, sort: "-updated_date" });
        const rows = Array.isArray(bodyOf(r).items) ? bodyOf(r).items : [];
        const stamp = rows.map((r) => `${r?.id}:${r?.updated_date}`).join("|");
        if (last && stamp !== last && !stopped) callback({ type: "update", data: null });
        last = stamp;
      } catch (err) {
        if (isForbidden(err)) markDenied(entity);
        // Transient gateway/rate-limit failure — retry on the next tick.
      }
    };
    check();
    const timer = setInterval(check, 120000);
    return () => {
      stopped = true;
      clearInterval(timer);
    };
  },
};

const proxy = (name) => new Proxy({}, {
  get(_, method) {
    const fn = METHODS[method];
    if (fn) return (...args) => fn(name, ...args);
    return () => Promise.reject(new Error(`${name}.${String(method)} is not available to staff reads`));
  },
});

export const staffEntities = new Proxy({}, {
  get(_, name) {
    if (typeof name !== "string") return undefined;
    return proxy(name);
  },
});

// One gateway call → rows for many entities. Uses staffDataRead batch mode so
// a page mount can fetch its whole catalog set in a single request instead of
// a dozen parallel reads hitting the rate limit.
//   const { PermitLocality, GlobalSettings } = await loadEntitiesBatch([
//     { entity: "PermitLocality", sort: "name" },
//     { entity: "GlobalSettings", limit: 10 },
//   ]);
export const loadEntitiesBatch = (requests) => {
  if (!hasSession()) return Promise.resolve({});
  const live = (requests || []).filter((r) => !isDenied(r?.entity));
  if (live.length === 0) return Promise.resolve({});
  return invokeFleet("staffDataRead", { entities: live }).then((r) => {
    const body = bodyOf(r);
    (body.denied || []).forEach(markDenied);
    return body.entities || {};
  });
};

